import { t } from './i18n.js';

// A third paragraph for each body, craft and story place, read on the photo page and in the
// sheet over a target looked at closely, after what readings.js, storyDetails.js and
// storyMore.js tell (the user, 2026-10-20: "사진보기 -> 읽을거리는 화면 1페이지까지 늘려줘",
// "읽을 글도 더 넣어, 칸만 늘리지 말고"): enough that the reading fills a phone's screen.
// Drafted from widely documented facts and not yet checked against sources one by one.
export const PHOTO_MORE = {
  sun: t("태양의 질량은 태양계 전체의 99.86%를 차지하고, 나머지 대부분은 목성입니다. 태양은 1초에 수소 약 6억 톤을 헬륨으로 바꾸고, 그 과정에서 약 400만 톤이 에너지로 사라집니다. 이렇게 오래 타는데도 핵융합으로 잃은 질량은 지금까지 전체의 0.03%쯤입니다. 태양에서는 입자가 초속 약 400 → 800km로 쏟아져 나와 태양풍이 되어 태양계 끝까지 불어 갑니다. 1859년 9월 영국의 캐링턴이 흑점 위의 강한 섬광을 보았고, 이튿날 기록상 가장 강한 지자기 폭풍이 지구를 덮쳐 전신기가 불꽃을 튀겼으며 오로라가 열대 지방에서도 보였습니다."),
  mercury: t("수성의 중심에는 철로 된 큰 핵이 있어 반지름의 약 85%를 차지하고, 밀도는 지구 다음으로 높습니다. 작은 행성인데도 자기장이 있습니다. 가장 큰 충돌 흔적은 지름 약 1,550km의 칼로리스 분지입니다. 수성의 궤도가 뉴턴의 계산과 조금씩 어긋나자 19세기에는 안쪽에 벌컨이라는 행성이 있다는 설까지 나왔지만, 1915년 아인슈타인의 일반 상대성 이론이 그 어긋남을 설명했습니다. 메신저는 2015년 4월 30일 연료가 떨어져 표면에 떨어지며 임무를 마쳤고, 유럽과 일본의 베피콜롬보가 2026년 11월 수성 궤도에 들어갈 예정입니다."),
  venus: t("금성은 자전 주기가 243일로 공전 주기 225일보다 깁니다. 1761년 로모노소프는 금성이 태양 앞을 지나갈 때 금성 둘레에 빛 고리가 번지는 것을 보고 금성에 대기가 있다고 짐작했습니다. 1970년 베네라 7호는 다른 행성 표면에서 신호를 보낸 첫 탐사선으로, 23분 동안 약 475도라는 온도를 알렸습니다. 1990년부터 1994년까지 미국의 마젤란은 레이더로 표면의 98%를 지도로 그렸고, 화산과 용암 평원이 곳곳에 펼쳐진 모습을 보여 주었습니다."),
  earth: t("지구는 중심으로 갈수록 뜨거워져, 고체인 철 내핵의 온도가 태양 표면과 비슷한 약 5,400도입니다. 내핵을 둘러싼 액체 외핵이 움직이며 자기장을 만듭니다. 기원전 240년쯤 에라토스테네스는 두 도시에서 막대 그림자의 길이를 재어 지구 둘레를 계산했고, 그 값이 오늘날의 값과 크게 다르지 않았다고 전해집니다. 1968년 12월 아폴로 8호의 우주비행사들은 달 뒤로 떠오르는 지구를 사진으로 찍었습니다. 지구의 하루는 정확히 24시간이 아니라 별을 기준으로 23시간 56분이고, 대기에 산소가 쌓이기 시작한 것은 광합성 생물이 늘어난 약 24억 년 전입니다."),
  moon: t("달의 인력은 바닷물을 끌어 하루에 두 번씩 밀물과 썰물을 만들고, 그 마찰로 지구의 자전이 아주 천천히 느려집니다. 1959년 소련의 루나 3호가 지구에서 보이지 않는 달의 뒷면을 처음 찍었습니다. 1969년 7월 20일 아폴로 11호의 닐 암스트롱과 버즈 올드린이 처음으로 달 위에 내렸고, 아폴로 계획 전체로 월석 약 382kg을 가져왔습니다. 낮에는 127도까지 오르고 밤에는 영하 173도까지 떨어집니다. 2019년 1월에는 중국의 창어 4호가 달의 뒷면에 처음으로 내렸습니다."),
  mars: t("화성의 이름은 붉은빛 때문에 로마 신화의 전쟁의 신에서 따왔습니다. 1965년 매리너 4호가 처음 가까이서 찍은 사진은 분화구뿐인 달 같은 땅을 보여 주었습니다. 1976년에는 바이킹 1호와 2호가 처음으로 표면에 내려 흙을 분석했습니다. 2021년 2월 퍼서비어런스가 제제로 분화구에 내렸고, 함께 간 헬리콥터 인저뉴어티는 4월 19일 다른 행성에서 처음으로 동력 비행에 성공해 2024년 1월까지 72번 날았습니다. 화성에서는 지구의 하루 대신 24시간 39분 35초를 한 날로 세어 솔이라 부릅니다."),
  phobos: t("포보스라는 이름은 그리스 신화에서 전쟁의 신 아레스의 아들인 공포의 신에서 왔습니다. 큰 분화구 스티크니는 발견자 아사프 홀의 아내 앤절린 스티크니의 처녀 때 성입니다. 평균 밀도가 1cm³에 1.9g쯤으로 바위보다 낮아, 속에 빈 곳이 많은 돌무더기일 수 있습니다. 표면에는 스티크니 쪽에서 뻗은 듯한 긴 홈이 줄지어 있습니다. 1726년에 나온 소설 걸리버 여행기에는 화성에 위성이 둘 있다는 대목이 나오는데, 실제 발견보다 150년도 더 앞섰습니다. 일본이 포보스의 흙을 가져올 탐사선 MMX를 준비하고 있습니다."),
  deimos: t("아사프 홀은 위성 찾기를 그만두려 했으나 아내 앤절린이 하룻밤만 더 해 보라고 권했고, 그날 밤 1877년 8월 데이모스를 찾았다고 전해집니다. 이름은 그리스 신화에서 아레스의 아들인 공황의 신에서 왔습니다. 데이모스는 화성의 하루와 비슷한 시간에 도는 궤도 가까이에 있어, 화성에서 한번 뜨면 이틀 넘게 하늘에 머뭅니다. 지름이 12km쯤으로 작아 탈출 속도가 초속 5.6m밖에 안 되고, 세게 던진 공이 우주로 날아갈 만큼 중력이 약합니다. 겉이 어둡고 탄소가 많아 보이는 점이 소행성과 닮았습니다."),
  jupiter: t("목성의 질량은 나머지 행성을 모두 합친 것의 2.5배쯤이지만, 태양의 1,000분의 1밖에 안 되어 별이 되지 못했습니다. 1973년 파이오니어 10호가 처음 가까이 갔고, 1995년부터 2003년까지 갈릴레오가 돌며 대기 속으로 탐사정을 떨어뜨렸습니다. 2016년부터는 주노가 극지방 위로 지나며 구름 속을 살피고 있습니다. 1994년 7월에는 슈메이커-레비 9 혜성이 21조각으로 쪼개져 엿새에 걸쳐 목성에 부딪혔고, 지구에서도 보이는 검은 흔적이 남았습니다."),
  io: t("이오는 1610년 1월 갈릴레이가 찾았고, 이름은 제우스의 사랑을 받은 요정에서 왔습니다. 1979년 3월 보이저 1호의 사진에서 린다 모라비토가 가장자리에 솟은 구름 같은 것이 화산 기둥임을 알아보았습니다. 기둥은 높이 300km에 이르기도 합니다. 가장 큰 화산 로키 파테라는 지름이 200km가 넘는 용암 호수를 품고 있고, 용암은 1,200도가 넘는 곳도 있습니다. 이오, 유로파, 가니메데는 공전 주기가 1 대 2 대 4의 비로 맞물려 있어, 서로 끌어당기는 힘이 이오의 궤도를 계속 일그러뜨립니다."),
  europa: t("갈릴레오 탐사선이 1990년대 말 유로파 곁의 자기장이 달라지는 것을 재어, 얼음 아래에 전기가 통하는 소금물이 있다는 근거를 얻었습니다. 2012년 허블 우주망원경은 남극 쪽에서 수증기 기둥이 솟는 것으로 보이는 흔적을 찍었습니다. 얼음 껍질의 두께는 15에서 25km쯤으로 봅니다. 목성의 강한 방사선이 표면에 쏟아져, 사람이 그냥 서 있으면 하루 안에 치명적인 양을 받습니다. 유로파 클리퍼는 2024년 10월 14일 발사되었고, 49번 유로파 곁을 지나며 얼음 두께와 바다의 소금기를 재고 생명이 살 만한 조건인지 살필 예정입니다."),
  ganymede: t("가니메데라는 이름은 그리스 신화에서 제우스의 술시중을 들게 된 트로이의 미소년에서 왔습니다. 1996년 갈릴레오 탐사선이 위성으로는 처음으로 가니메데에서 자기장을 찾아냈습니다. 2015년 허블 우주망원경은 가니메데의 오로라가 흔들리는 모양을 살펴, 땅속에 소금물 바다가 있다는 증거를 보여 주었습니다. 그 바다는 지구의 모든 바다를 합친 것보다 물이 많을 것으로 봅니다. 2022년 6월 주노가 1,000km 안으로 지나가며 얼음 표면을 가까이에서 찍었습니다. 유럽의 주스는 2031년 목성에 닿고, 2034년 12월 가니메데를 도는 궤도에 들어갈 예정입니다."),
  callisto: t("이름은 제우스의 사랑을 받다가 곰으로 변한 요정에서 왔고, 1610년 갈릴레이가 찾았습니다. 목성에서 약 188만km 떨어져 있어 큰 위성 가운데 가장 바깥을 돕니다. 이오나 유로파와 달리 궤도가 다른 위성과 맞물리지 않아 조석으로 열이 거의 나지 않고, 그래서 속이 바위와 얼음으로 완전히 나뉘지 못하고 섞여 있는 것으로 봅니다. 갈릴레오 탐사선이 잰 자기장의 변화는 얼음 아래 깊은 곳에 소금물 바다가 있을 가능성을 보여 줍니다. 표면에는 햇빛에 얼음이 깎여 남은 높이 수십 m의 뾰족한 언덕이 솟아 있고, 이산화탄소로 된 아주 옅은 대기가 있습니다."),
  saturn: t("토성이라는 이름은 로마 신화의 농사 신 사투르누스에서 왔고, 영어의 토요일도 같은 뿌리입니다. 1610년 갈릴레이는 토성 양옆의 고리를 두 개의 큰 위성으로 보았고, 1655년 하위헌스가 얇고 평평한 고리가 둘러싸고 있다고 풀이했습니다. 토성은 29.5년에 한 번 태양을 돌고, 자전축이 26.7도 기울어 고리의 모습이 달라집니다. 15년쯤마다 고리가 옆에서 보이는 때가 와서 지구에서는 고리가 거의 사라진 것처럼 보이며, 가장 최근은 2025년 3월이었습니다. 카시니는 연료가 다하자 2017년 9월 15일 토성 대기로 뛰어들어 임무를 끝냈습니다."),
  mimas: t("미마스라는 이름은 그리스 신화의 거인에서 왔고, 이름을 붙인 사람은 윌리엄 허셜의 아들 존 허셜입니다. 가장 큰 분화구 허셜은 아버지이자 발견자인 윌리엄 허셜을 기리는 이름입니다. 밀도는 1cm³에 1.15g으로 얼음에 바위가 조금 섞였습니다. 고리 안쪽 가장자리의 알갱이는 공전 주기가 미마스의 절반이 되는 자리에서 미마스에게 되풀이해 끌려 빠져나가므로 카시니 간극이 비게 됩니다. 2024년의 연구는 미마스의 궤도가 미세하게 흔들리는 것을 근거로, 얼음 아래에 생긴 지 500만 → 1,500만 년밖에 안 된 바다가 있을 수 있다고 보고했습니다."),
  enceladus: t("카시니는 2015년 10월 28일 엔셀라두스 남극에서 49km 위를 스치고 지나가며 물기둥 속에서 수소 분자를 찾았습니다. 수소는 바다 밑바닥의 뜨거운 바위가 물과 반응할 때 나오는 것으로 봅니다. 앞서 바다 밑에서 씻겨 나온 듯한 규소 알갱이가 발견되어, 물이 90도 넘게 뜨거워진 곳이 있다고 풀이되기도 했습니다. 남극의 얼음 껍질은 두께가 5km쯤으로 얇아 물이 새어 나오기 쉽습니다. 호랑이 줄무늬를 따라 100개가 넘는 분출구가 있고, 초당 약 200kg의 수증기를 뿜는 것으로 잴 수 있었습니다."),
  tethys: t("테티스라는 이름은 그리스 신화의 티탄 여신에서 왔고, 토성 위성의 이름들은 1847년 존 허셜이 지었습니다. 표면은 햇빛을 아주 잘 되비추는데, 엔셀라두스가 뿜은 얼음 가루가 내려앉아 새 눈처럼 덮고 있기 때문입니다. 오디세우스 분화구는 생긴 뒤 오랜 세월 가운데가 천천히 내려앉아 지금은 둥근 사발처럼 펴져 있고, 이름은 호메로스의 오디세이아 주인공에서 땄습니다. 이타카 협곡의 이름도 오디세우스의 고향 섬에서 왔습니다. 카시니는 2005년과 2015년에 테티스 곁을 가까이 지나며 표면을 찍었습니다."),
  dione: t("디오네의 이름은 그리스 신화에서 제우스의 연인이며 아프로디테의 어머니로 알려진 티탄 여신에서 왔습니다. 밀도가 1cm³에 1.48g으로 타이탄과 엔셀라두스 다음으로 높아, 바위가 전체의 3분의 1쯤 됩니다. 카시니는 2005년 디오네 곁을 스치며 뒤쪽 반구의 밝은 줄무늬가 칠을 한 것이 아니라 얼음 절벽임을 확인했습니다. 2016년의 연구는 중력을 재어, 바위 핵 위 약 100km 깊이에 바다가 있을 수도 있다고 보았습니다. 2012년에는 아주 옅은 산소 대기가 있는 것도 확인되었습니다. 엔셀라두스와는 공전 주기가 1 대 2로 맞물려 서로 영향을 줍니다."),
  rhea: t("레아의 이름은 그리스 신화에서 제우스의 어머니이자 크로노스의 아내인 티탄 여신에서 왔습니다. 크로노스는 로마에서 토성의 이름이 된 사투르누스에 해당합니다. 카시니는 이아페투스(1671년)에 이어 1672년 12월 레아를 찾았고, 1684년 테티스와 디오네까지 합쳐 토성의 위성 넷을 찾았습니다. 밀도가 1cm³에 1.24g으로 낮아 바위가 전체의 4분의 1쯤입니다. 가장 큰 분화구 티라와는 지름이 약 360km에 이릅니다. 2008년 카시니의 입자 측정 자료를 근거로 레아에 고리가 있을 수 있다는 주장이 나와 화제가 되었지만, 이후 근접 사진에서는 고리를 찾지 못했습니다."),
  titan: t("타이탄은 1655년 3월 하위헌스가 찾은 토성의 첫 위성이고, 이름은 존 허셜이 지었습니다. 가장 큰 바다 크라켄 해는 길이가 1,000km가 넘고 넓이가 카스피해와 맞먹습니다. 하위헌스는 2005년 1월 14일 낙하산으로 2시간 반쯤 내려가 표면에 닿은 뒤 70분 남짓 신호를 보냈고, 표면은 젖은 모래 같은 땅에 둥근 얼음 자갈이 널려 있었습니다. 대기가 두껍고 중력이 지구의 7분의 1이라, 사람이 팔에 날개를 달면 날 수 있다고 합니다. 드래건플라이는 2028년 발사해 2034년 도착할 예정입니다."),
  iapetus: t("이아페투스는 이름이 그리스 신화의 티탄에서 왔습니다. 검은 쪽은 카시니 지역, 밝은 쪽은 롱스보 지역이라 부르는데, 롱스보라는 이름은 중세 서사시 롤랑의 노래에서 왔습니다. 적도의 산줄기는 폭이 200km쯤이고 태양계에서 손꼽히게 높습니다. 궤도는 토성의 적도면에서 15도쯤 기울어 있습니다. 검은 먼지는 토성 바깥쪽의 포이베 고리에서 왔다는 설이 있는데, 이 고리는 2009년 스피처 우주망원경이 찾았습니다. 카시니 탐사선은 2007년 9월 10일 1,600km 위를 지나며 검은 땅과 흰 땅의 경계를 가까이서 찍었습니다."),
  uranus: t("천왕성은 1781년 3월 13일 윌리엄 허셜이 처음에는 혜성으로 생각했습니다. 곧 궤도가 원에 가깝다는 것이 알려져 새 행성으로 인정되었고, 허셜은 영국 왕 조지 3세를 기려 이름을 붙이려 했으나 독일의 요한 보데가 제안한 우라노스가 자리 잡았습니다. 천왕성 대기의 가장 낮은 온도는 영하 224도로, 행성에서 잰 값 가운데 가장 낮습니다. 안쪽에서 나오는 열이 거의 없기 때문입니다. 고리는 1977년 3월 천왕성이 별을 가리는 것을 관측하다가 처음 찾았습니다. 보이저 2호는 1986년 1월 24일 약 8만 1,500km까지 다가갔습니다."),
  miranda: t("미란다는 이름이 셰익스피어의 희곡 템페스트에 나오는 프로스페로의 딸에게서 왔습니다. 경주장처럼 보이는 무늬를 가진 땅 셋(아든, 인버네스, 엘시노어)이 있는데, 코로나라고 부릅니다. 한때는 미란다가 부서졌다가 다시 뭉쳤다는 설도 있었지만, 지금은 속의 열이 얼음을 밀어 올려 생긴 것으로 봅니다. 보이저 2호는 1986년 1월 24일 미란다에 약 3만km까지 가까이 다가갔는데, 천왕성의 다른 큰 위성에는 이렇게 가까이 가지 못했습니다. 그래서 미란다의 사진이 가장 자세합니다."),
  ariel: t("래셀은 영국 리버풀의 양조업자로, 직접 망원경을 만들어 별을 보던 아마추어였습니다. 1851년 10월 24일 아리엘과 움브리엘을 찾았고, 1846년에는 해왕성의 위성 트리톤도 찾았습니다. 아리엘의 이름은 알렉산더 포프의 시에 나오는 공기의 요정에서 왔고, 존 허셜이 1852년에 지었습니다. 천왕성의 위성 가운데 아리엘에서 이산화탄소 얼음이 가장 뚜렷하게 보입니다. 표면에 얽힌 골짜기는 껍질이 갈라지며 생긴 것으로 보고, 가장 큰 골짜기들은 폭이 수십 km에 이릅니다."),
  umbriel: t("움브리엘의 이름은 알렉산더 포프의 시 머리타래의 강탈에 나오는 우울한 정령에서 왔고, 라틴어로 그림자를 뜻하는 움브라와도 이어집니다. 이름은 래셀의 부탁을 받아 존 허셜이 1852년에 지었습니다. 햇빛을 되비추는 비율은 아리엘의 절반쯤입니다. 크기와 거리가 비슷한데도 이렇게 다른 까닭은 아직 밝혀지지 않았습니다. 운다 분화구는 지름이 약 131km입니다. 천왕성에서 약 26만 6천km 떨어져 돌고, 보이저 2호는 1986년 약 32만 5천km 밖에서 지나갔기 때문에, 사진 속 가장 작은 지형이 5km쯤입니다."),
  titania: t("티타니아의 이름은 존 허셜이 1852년에 지었습니다. 밀도는 1cm³에 1.71g이고, 가장 큰 분화구 거트루드는 지름이 약 326km이며 이름은 햄릿의 어머니에게서 땄습니다. 메시나 협곡의 이름은 셰익스피어의 희곡 헛소동의 배경이 된 도시 메시나에서 왔습니다. 보이저 2호는 1986년 약 36만 5천km까지 다가가 표면의 40%쯤을 찍었습니다. 2001년 9월에는 티타니아가 별 앞을 지나는 것을 관측했는데, 짙은 대기는 없다는 것이 확인되었습니다. 어두운 물질이 깔린 분화구도 있습니다."),
  oberon: t("허셜은 1787년 1월 11일 티타니아와 오베론을 같은 날 찾았습니다. 또 위성 네 개를 더 보았다고 믿었지만, 나중에 모두 착각이었음이 밝혀졌습니다. 이름은 1852년 존 허셜이 지었습니다. 가장 큰 분화구 햄릿은 지름이 약 206km이고, 오셀로 분화구가 114km로 뒤따릅니다. 오베론은 천왕성에서 약 58만 4천km 떨어져 돕니다. 보이저 2호는 1986년 오베론에 약 47만km까지만 다가가 표면의 40%쯤을 찍었고, 그래서 오베론의 반대편은 아직 모습을 알지 못합니다."),
  neptune: t("해왕성은 프랑스의 위르뱅 르베리에와 영국의 존 쿠치 애덤스가 따로따로 자리를 셈했습니다. 르베리에의 계산을 받은 독일의 요한 갈레가 1846년 9월 23일 밤 베를린 천문대에서 계산한 자리에서 1도 안 떨어진 곳에서 바로 행성을 찾았습니다. 이름은 로마 신화의 바다의 신에서 왔습니다. 보이저 2호는 1989년 8월 25일 구름 위 약 4,950km까지 다가갔습니다. 해왕성은 태양에서 받는 열보다 2.6배나 많은 열을 안에서 내놓습니다. 고리는 다섯 개이고, 가장 바깥 고리에는 밝은 덩어리가 몇 개 있습니다."),
  triton: t("트리톤은 해왕성이 발견된 지 17일 뒤인 1846년 10월 10일 영국의 윌리엄 래셀이 찾았습니다. 이름은 그리스 신화에서 바다의 신 포세이돈의 아들입니다. 해왕성을 도는 궤도가 해왕성의 적도에 대해 157도 기울어 거꾸로 돕니다. 질소 얼음이 햇빛을 잘 되비춰 표면이 밝으며, 질소로 된 대기는 지구의 7만분의 1쯤으로 옅습니다. 보이저 2호가 지나간 1989년은 남반구가 여름인 때였고, 간헐천 줄기는 남극 쪽 밝은 땅 위에 모여 있었습니다. 표면 아래에 바다가 있을 가능성도 이야기됩니다."),
  ceres: t("세레스라는 이름은 로마 신화의 곡식의 여신에서 왔고, 피아치가 일하던 시칠리아의 수호 여신이기도 합니다. 피아치는 41일 동안 관측하다 병으로 보지 못하게 되었고, 세레스가 태양 빛 속으로 사라지자 가우스가 새 계산법으로 궤도를 셈해 1801년 12월 다시 찾을 수 있게 했습니다. 던 탐사선은 2007년 발사되어 2015년 3월 6일 세레스에 도착했고, 2018년 11월 1일 연료가 다해 임무를 끝냈습니다. 지금도 세레스 둘레를 돌고 있습니다. 오카토르 분지의 소금은 탄산나트륨이 많은데, 이는 비교적 최근까지 소금물이 올라왔다는 뜻입니다."),
  pluto: t("명왕성의 영어 이름 플루토는 영국 옥스퍼드의 11세 소녀 베니셔 버니가 지어 제안했습니다. 로마 신화의 저승의 신 이름입니다. 클라이드 톰보는 미국 로웰 천문대에서 1930년 1월에 찍은 사진 건판 두 장을 2월 18일 견주어 움직이는 점을 찾았고, 발표는 같은 해 3월 13일이었습니다. 뉴허라이즌스는 2006년 1월에 발사되어 2015년 7월 14일 약 1만 2,500km까지 다가갔습니다. 톰보의 유해 일부가 탐사선에 실려 있습니다. 명왕성에는 위성이 다섯 개 있는데, 카론, 닉스, 히드라, 케르베로스, 스틱스입니다."),
  charon: t("카론의 이름은 제임스 크리스티가 아내 샤를린의 애칭 샤르에 맞춰 골랐고, 그리스 신화에서 죽은 이를 강 건너 저승으로 데려다주는 뱃사공 카론과 이어집니다. 크리스티는 1978년 6월 미국 해군 천문대에서 명왕성 사진의 둥근 상이 한쪽으로 불룩한 것을 보고 위성을 알아챘습니다. 카론의 북극에는 모도르 마쿨라라는 붉은 얼룩이 있고, 지름이 약 475km입니다. 적도 둘레에는 깊이 최대 7.5km의 협곡이 이어집니다. 카론은 명왕성에서 약 1만 9,600km 떨어져 돌고, 2005년 허블이 명왕성의 작은 위성 닉스와 히드라를 찾은 뒤에야 위성이 다섯 개임이 알려지기 시작했습니다."),
  halley: t("핼리 혜성은 1066년 노르만 정복 때에도 나타나 바이외 태피스트리에 그려져 있습니다. 핼리는 1682년 혜성을 보고 계산해 1758년에 돌아올 것이라 했으나 1742년에 세상을 떠났고, 1758년 12월 25일 독일의 농부 요한 팔리치가 직접 찾아 예언이 맞았음이 밝혀졌습니다. 1910년 지구는 이 혜성의 꼬리 속을 지나갔는데, 꼬리에 독가스가 있다는 소문이 돌았지만 피해는 없었습니다. 1986년에는 소련의 베가 1호와 2호, 일본의 사키가케와 스이세이, 유럽의 지오토가 함께 핵을 살피러 갔습니다."),
  haleBopp: t("앨런 헤일은 미국 뉴멕시코에서, 토머스 밥은 애리조나에서 같은 날 혜성을 보았습니다. 헤일은 오랫동안 혜성을 살펴 온 천문학자였고, 밥은 망원경으로 별을 구경하던 아마추어였습니다. 1997년 4월 1일 근일점에서 태양까지의 거리는 약 1억 3,700만km였고, 지구에는 3월 22일 약 1억 9,700만km까지 가까이 왔습니다. 이 혜성에서는 처음으로 나트륨으로 된 꼬리가 확인되었습니다. 먼지 꼬리와 이온 꼬리 외에 세 번째 꼬리였고, 이렇게 먼 곳에서 이토록 활발히 먼지를 뿜은 혜성도 드물었습니다."),
  churyumov: t("추류모프는 알마아타 천문대에서 게라시멘코가 다른 혜성을 찍은 사진 건판을 살피다 가장자리에서 한 혜성을 보았는데, 한참 뒤에 그것이 원래 찍으려던 혜성이 아니라 새 혜성임이 밝혀졌습니다. 로제타는 2004년 3월 2일 발사되었고, 2016년 9월 30일 혜성 표면에 내려앉으며 임무를 끝냈습니다. 필레는 배터리로 약 64시간 일하며 유기 분자를 찾았고, 2015년 6월 잠시 깨어나 신호를 보냈습니다. 혜성 곁의 기체에서는 썩은 달걀과 말 오줌 냄새를 닮은 황화수소와 암모니아가 확인되었습니다. 핵의 밀도는 물의 절반쯤이어서 속에 빈 곳이 많습니다."),
  vesta: t("돈 탐사선은 2007년 발사되어 2011년 7월 16일 베스타에 도착했고 2012년 9월 5일 떠났습니다. 천체 둘을 차례로 돈 첫 탐사선으로, 제논 이온 엔진으로 베스타에서 세레스로 옮겨 갔습니다. 베스타의 철 핵은 반지름이 약 110km입니다. 지구에서 찾은 베스타 운석은 하워다이트, 유크라이트, 디오제나이트 세 갈래라서 머리글자를 따 HED 운석이라 부릅니다. 이 운석들 덕에 사람들은 가 보기 전부터 베스타가 속이 나뉜 천체임을 알았습니다."),
  bennu: t("오시리스-렉스는 2016년 9월 8일 발사되었습니다. 샘플 용기의 뚜껑을 고정한 나사 두 개가 풀리지 않아 2024년 1월에야 열렸습니다. 2025년 1월 연구진은 베누 시료에서 단백질 재료인 아미노산 20종 가운데 14종과 DNA와 RNA의 염기 5종이 모두 나왔다고 발표했습니다. 이것은 생명의 재료가 소행성을 타고 지구로 왔을 수 있다는 생각을 뒷받침합니다. 오시리스-렉스는 임무를 이어, 이름을 오시리스-에이펙스로 바꾸고 2029년 4월 소행성 아포피스에 다가갈 예정입니다."),
  ryugu: t("하야부사2는 2014년 12월 3일 발사되었고, 하야부사는 일본말로 송골매를 뜻합니다. 2018년 10월 3일 독일과 프랑스가 만든 착륙선 마스코트가 류구에 내려 17시간 동안 배터리로 움직이며 표면을 살폈습니다. 시료는 지구에서 찾은 가장 변하지 않은 CI 운석과 닮았는데, 지구 대기와 물을 만나지 않아 오염이 없다는 점이 다릅니다. 2023년에는 시료에서 아미노산 20종 넘게 확인되었다고 보고되었습니다. 가장 큰 바위 오토히메는 높이가 약 160m이고, 이름은 용궁의 공주에서 왔습니다."),
  didymos: t("디디모스는 규소가 많은 돌로 이루어진 S형 소행성이고, 밀도는 물의 약 2.2배입니다. 가운데가 불룩한 팽이 모양이며 적도를 따라 능선이 솟아 있습니다. 태양을 도는 길이 지구 궤도와 겹치는 아폴로형 소행성이지만, 다트가 부딪친 2022년 9월에는 지구에서 약 1,100만km 떨어져 있었습니다. 이는 달까지 거리의 29배쯤입니다. 쌍소행성은 지구 가까이 오는 소행성의 15%쯤을 차지하는 것으로 봅니다."),
  dimorphos: t("다트가 성공했다고 보는 기준은 공전 주기를 73초 이상 줄이는 것이었는데, 실제로는 32분이 줄어 그 기준의 25배가 넘었습니다. 디모르포스는 단단한 한 덩이가 아니라 바위가 느슨하게 모인 더미로 보이며, 부딪친 뒤 흩어진 물질이 몇 달 동안 꼬리를 이루었습니다. 다트의 마지막 사진은 부딪치기 2초 전에 찍은 것으로, 폭 약 31m의 땅이 담겼습니다. 다트는 마지막 4시간을 목표를 스스로 찾아가는 항법으로 날았습니다."),
  apophis: t("아포피스는 태양을 0.9년에 한 바퀴 돌면서 지구 궤도 안쪽과 바깥쪽을 오가는 아텐형 소행성입니다. 하루는 약 30시간입니다. 2029년 4월 13일 가장 가까울 때는 3등급대 밝기로, 북두칠성의 별들과 비슷하게 보이며 밤하늘을 빠르게 가로질러 갑니다. 2021년 미국 골드스톤과 그린뱅크의 전파 망원경이 레이더로 쟀고, 그 정밀한 위치로 앞으로 100년 넘게 안전하다는 결론이 나왔습니다."),
  oumuamua: t("오우무아무아는 9월 9일 태양에 가장 가까이 갔을 때 약 3,800만km 거리까지 다가왔는데, 수성 궤도 안쪽입니다. 10월 14일에는 지구에서 약 2,400만km까지 다가왔습니다. 거문고자리의 직녀성 쪽에서 왔으며, 페가수스자리 쪽으로 떠나고 있습니다. 어느 별에서 왔는지는 알 수 없습니다. 별 사이 천체라는 사실은 궤도의 이심률이 1.2로 1보다 큰 것에서 알아냈습니다. 발견 뒤 석 달 가까이 관측이 이어졌습니다."),
  atlas3i: t("아틀라스는 소행성 지구 충돌 마지막 경보 체계라는 영어 이름의 머리글자를 딴 것으로, 하와이와 칠레와 남아프리카 등에 망원경이 있습니다. 3I의 I는 별 사이를 뜻하는 영어 단어의 머리글자이고 앞의 3은 세 번째라는 번호입니다. 이 혜성의 궤도 이심률은 약 6으로, 보리소프 혜성(3.4)과 오우무아무아(1.2)보다 훨씬 큽니다. 이심률이 클수록 궤도는 곧게 뻗어 태양에 묶이지 않습니다. 태양에서 가장 가까운 거리는 약 1.36AU였습니다."),
  eris: t("에리스는 2010년 11월 칠레에서 별을 가리는 순간을 지켜본 관측으로 지름이 2,326km로 재어졌습니다. 명왕성은 뉴허라이즌스가 2015년에 약 2,377km로 쟀으니 에리스가 근소하게 작습니다. 처음에는 에리스가 명왕성보다 커 보였습니다. 위성 디스노미아는 2005년 9월 하와이 켁 망원경으로 찾았고, 지름은 700km 안팎으로 짐작합니다. 에리스의 무게는 이 위성의 궤도를 재어 알아냈습니다."),
  haumea: t("2017년 하우메아가 별을 가리는 순간을 관측해 몸의 크기가 세 방향으로 약 2,322, 1,704, 1,138km로 다시 재어졌습니다. 무게는 명왕성의 약 3분의 1입니다. 위성 히이아카는 지름 약 300km이고 나마카는 약 170km입니다. 하우메아의 궤도는 행성들이 도는 면에서 약 28도 기울어 있습니다. 같은 충돌로 생긴 얼음 조각들의 무리는 2007년에 처음 알려졌습니다. 표면은 거의 순수한 물 얼음이라 눈처럼 밝습니다."),
  makemake: t("마케마케는 태양에서 가장 가까울 때 약 38AU, 가장 멀 때 약 53AU 떨어지고, 궤도는 행성들이 도는 면에서 약 29도 기울어 있습니다. 표면은 햇빛의 약 80%를 되비칩니다. 무게는 명왕성의 4분의 1쯤으로, 위성 MK2의 궤도를 재어 알아냈습니다. MK2는 2015년 4월 허블 사진에서 찾아 2016년에 발표했습니다. 해왕성 바깥 천체에서 이렇게 밝게 빛나는 것은 몇 되지 않습니다. 발견 당시에는 태양에서 약 52AU 거리에 있었습니다."),
  sedna: t("세드나는 태양에서 가장 가까울 때도 50AU보다 멀리 떨어진 세드노이드라는 무리의 대표입니다. 같은 무리로 2012 VP113(2014년 발표)과 2015 TG387(2018년 발표)이 있습니다. 모두 해왕성의 중력이 거의 닿지 않는 궤도를 도는 것이 특징입니다. 허블 우주망원경으로 위성을 찾아보았지만 나오지 않았고, 하루의 길이도 아직 분명하지 않습니다. 발견 때 세드나는 태양에서 약 90AU 떨어져 있었고, 사진 속에서 아주 조금씩만 움직였습니다."),
  arrokoth: t("큰 덩이 웨누는 약 22km, 작은 덩이 웨요는 약 15km이고, 15.9시간에 한 번 돕니다. 두 덩이는 아주 느린 속도로 만나 붙은 것으로 보여 충돌 자국이 거의 없습니다. 처음 별명 울티마 툴레는 옛 뜻이 나치와 이어진다는 비판이 나와 쓰지 않게 되었고, 2019년 11월 아로코스라는 이름이 발표되었습니다. 가장 또렷한 사진은 한 점이 33m를 나타냅니다. 두 덩이가 만나는 목 부분은 둘레보다 밝은 띠로 보입니다."),
  hyperion: t("히페리온은 1981년 보이저 2호의 사진으로 처음 자세히 보였고, 1984년 미국의 잭 위즈덤 등은 이런 모양과 궤도에서는 자전축이 제멋대로 흔들릴 수밖에 없다는 계산을 내놓았습니다. 이렇게 어지럽게 구르는 자연 천체가 확인된 것은 처음입니다. 밀도는 물의 약 0.5배입니다. 카시니는 어두운 물질에서 물 얼음, 이산화탄소, 유기물을 찾았습니다. 토성에서 약 148만km 떨어진 곳을 돌고, 겉은 햇빛의 25%쯤을 되비칩니다."),
  phoebe: t("포에베는 토성의 큰 위성들과 달리 거꾸로 도는 작은 위성입니다. 카시니는 표면에서 물 얼음, 이산화탄소, 유기물을 찾았습니다. 밀도는 물의 약 1.6배로, 명왕성이나 트리톤과 비슷해 카이퍼대에서 왔다는 생각을 뒷받침합니다. 카시니의 가까운 만남은 이날 한 번뿐이었습니다. 옅은 고리는 2009년 앤 버비서 등이 스피처 자료에서 찾아냈습니다. 밀도가 높다는 것은 얼음에 돌이 섞여 있다는 뜻입니다."),
  proteus: t("프로테우스는 NASA 제트추진연구소의 스티븐 시노트가 보이저 2호의 사진 속에서 찾아냈고, 처음에는 S/1989 N 1이라는 임시 번호로 불렸습니다. 겉에는 길게 뻗은 골과 비탈이 보입니다. 보이저 2호는 이때 해왕성의 위성을 여섯 개 새로 찾았고, 프로테우스가 그중 가장 큽니다. 네레이드보다 크지만 어둡고 해왕성에 바짝 붙어 있어 지구의 망원경으로는 오랫동안 보이지 않았습니다."),
  eurybates: t("루시는 2027년 8월 12일 에우리바테스와 퀘타를 지난 뒤 폴리멜레와 그 위성, 2028년 4월 레우코스, 2028년 11월 오루스를 차례로 지납니다. 에우리바테스는 탄소가 많은 C형으로 겉이 숯처럼 어둡습니다. 이 소행성들은 목성과 같은 12년 주기로 태양을 돌기 때문에, 루시는 한 번의 긴 여행으로 서로 다른 소행성 여럿을 만나게 됩니다. 루시가 보내올 자료는 이 소행성들이 태양계의 어느 곳에서 태어났는지 가늠하는 단서가 됩니다."),
  patroclus: t("반대로 앞쪽 무리에 있는 헥토르는 신화에서 파트로클로스를 쓰러뜨린 트로이의 왕자 이름입니다. 헥토르는 1907년 코프가 찾은 가장 큰 트로이 소행성으로, 길이 약 400km의 땅콩 모양이고 위성을 하나 거느립니다. 그래서 두 소행성은 신화와 반대로 서로 상대편 진영에 들어가 있는 셈입니다. 파트로클로스는 4.3일에 한 번 자전하며, 메노이티오스도 같은 시간에 돕니다. 이 둘은 아직 한 번도 가까이서 찍힌 적이 없습니다."),
  menoetius: t("파트로클로스와 메노이티오스를 합친 밀도는 물의 약 0.9배로, 돌로만 이루어졌다면 그 3배쯤 되었을 것입니다. 속이 얼음과 빈틈으로 가득하다는 뜻입니다. 두 천체는 거의 둥글고 크기가 비슷해 어느 쪽이 위성인지 가리기 어렵습니다. 루시는 2033년 3월 2일 이 짝을 마지막으로 찾아갑니다. 지금 아는 모습은 별을 가리는 시간으로 잰 윤곽뿐입니다. 둘 사이는 지구에서 보면 1초각의 몇 분의 1에 지나지 않아 큰 망원경이 아니면 가를 수 없습니다."),
  voyager1: t("2023년 11월부터 5개월 동안 보이저 1호는 뜻을 알 수 없는 신호만 보냈습니다. 컴퓨터 메모리 칩 하나가 고장 난 탓이었고, 2024년 4월 NASA가 프로그램을 다른 곳으로 옮겨 고쳤습니다. 이 탐사선의 컴퓨터는 1970년대에 만든 것입니다. 지구까지 신호가 오는 데 23시간쯤 걸리고, 2026년 11월쯤에는 빛이 하루 걸리는 거리, 약 260억km에 이릅니다. 금빛 레코드에는 사진 115장과 지구의 소리가 들어 있습니다."),
  voyager2: t("천왕성에서는 1986년 1월 24일 구름 위 약 8만 1,500km 거리를 지났고, 해왕성에서는 1989년 8월 25일 북극 위 약 4,950km까지 다가가 커다란 어두운 점과 트리톤에서 솟는 검은 기둥을 찍었습니다. 2023년 7월에는 잘못된 명령으로 안테나가 2도 틀어져 교신이 끊겼다가, 8월 초 강한 신호를 보내 되살렸습니다. 천왕성에서는 위성 미란다의 깊은 골짜기를, 해왕성에서는 시속 2,000km가 넘는 바람을 처음 보았습니다."),
  hubble: t("허블은 지상 약 540km 위를 95분에 한 바퀴 돕니다. 원래 1986년에 올라갈 계획이었으나 챌린저호 사고로 4년 늦어졌습니다. 1994년 슈메이커-레비 9 혜성이 목성에 부딪치는 모습을 찍었고, 2009년 마지막 수리 때는 새 카메라가 달렸습니다. 자세를 잡는 자이로가 하나씩 고장 나 2024년 6월부터 하나만으로 관측합니다. 2030년대 중반까지 쓸 수 있을 것으로 봅니다."),
  jwst: t("웹 망원경의 거울은 베릴륨 위에 금을 약 100nm 두께로 입혔고, 쓰인 금은 모두 48g쯤입니다. 금은 적외선을 잘 되비칩니다. 거울이 빛을 모으는 넓이는 25제곱미터로 허블의 6배쯤입니다. 첫 사진은 2022년 7월 12일에 공개되었습니다. 만드는 데 25년이 걸렸고 비용은 약 100억 달러였습니다. 연료는 20년 넘게 쓸 만큼 남아 있고, 이름은 아폴로 계획 때 NASA를 이끈 제임스 웹에서 왔습니다."),
  kepler: t("케플러의 카메라는 9,500만 화소로, 하늘 한 곳을 30분마다 찍었습니다. 2011년 별에서 물이 액체로 있을 수 있는 거리에 도는 행성 케플러 22b를 처음 확인했고, 2014년에는 그런 거리에서 도는 지구만 한 행성 케플러 186f를 찾았습니다. 바퀴 고장 뒤에는 K2라는 이름으로 2014년부터 2018년까지 황도를 따라 하늘 스무 곳 안팎을 차례로 살폈습니다. 케플러의 관측으로 지구보다 크고 해왕성보다 작은 행성이 가장 흔하다는 것이 드러났습니다. 우리 태양계에는 그런 행성이 하나도 없습니다."),
  chandra: t("찬드라의 첫 사진은 1999년 8월에 공개한 카시오페이아자리의 초신성 잔해였습니다. 2006년에는 두 은하단이 부딪치는 총알 은하단을 찍어, 보이는 기체와 보이지 않는 물질이 따로 떨어져 있는 모습으로 암흑 물질이 있다는 강한 증거를 냈습니다. 거울에는 이리듐을 입혔습니다. 원래 5년을 쓸 계획이었지만 25년 넘게 일하고 있습니다. 찬드라는 산스크리트어로 달을 뜻합니다. 찬드라는 우리 은하 중심의 블랙홀 궁수자리 A*가 때때로 번쩍이는 X선을 내는 것도 포착했습니다."),
  euclid: t("유클리드는 2023년 11월 7일 첫 시험 사진을 공개했고, 2025년 3월에는 하늘 63제곱도에서 은하 2,600만 개가 찍힌 첫 자료를 내놓았습니다. 2025년 2월에는 은하 NGC 6505를 둘러싼 아인슈타인 고리를 알렸습니다. 이름은 그리스의 수학자 유클리드에서 왔고, 가시광선 카메라는 6억 화소입니다. 이 카메라 하나가 보름달 두 개 넓이를 한 번에 찍습니다. 유클리드는 약 100억 년 전의 은하까지 보면서, 우주의 팽창이 시간에 따라 어떻게 빨라져 왔는지 재어 봅니다."),
  iss: t("국제우주정거장은 맑은 밤이면 맨눈으로 보입니다. 가장 밝을 때는 금성보다 밝습니다. 태양전지판의 넓이는 합쳐서 약 2,500제곱미터이고, 이것으로 전기를 75 → 90킬로와트 만듭니다. 지금까지 260명이 넘는 사람이 다녀갔고, 보통 여섯에서 일곱 명이 함께 지냅니다. 처음 올라간 부분은 러시아의 자랴 모듈로 1998년 11월 20일이었고, 2주 뒤 미국의 유니티 모듈이 붙었습니다."),
  tiangong: t("톈허를 올린 것은 2021년 4월 29일 창정 5호 B 로켓이었고, 그해 6월 17일 선저우 12호의 우주비행사 셋이 처음 들어가 약 90일을 지냈습니다. 중국은 앞서 2011년 톈궁 1호, 2016년 톈궁 2호라는 작은 시험 정거장을 띄웠고, 톈궁 1호는 교신이 끊긴 채 2018년 4월 2일 남태평양에 떨어졌습니다. 2022년 11월 선저우 14호 승무원이 조립을 마무리했습니다. 화물선 톈저우가 먹을 것과 연료를 실어 나릅니다. 앞으로 10년 넘게 쓰는 것이 목표입니다. 톈궁은 모듈을 더 붙여 여섯 개까지 늘릴 수 있게 설계되었습니다. 2021년 선저우 13호 승무원은 처음으로 여섯 달을 머물렀습니다."),
  sputnik: t("설계를 이끈 사람은 소련의 세르게이 코롤료프였고, 스푸트니크는 R-7 로켓에 실려 카자흐스탄의 바이코누르에서 올라갔습니다. 소련은 한 달 뒤인 1957년 11월 3일 개 라이카를 태운 스푸트니크 2호를 올렸고, 미국의 첫 위성 익스플로러 1호는 1958년 1월 31일에야 올라갔습니다. 신호는 20.005와 40.002메가헤르츠로 보냈고, 위성은 지구에서 215km 대 939km의 타원 궤도를 돌았습니다. 마지막 신호가 끊긴 뒤에도 두 달 반쯤 더 궤도를 돌았습니다."),
  mro: t("하이라이즈는 2008년 피닉스가 낙하산을 펴고 내려오는 모습을, 2012년에는 큐리오시티가, 2021년에는 퍼서비어런스가 내려오는 모습을 위에서 찍었습니다. 분광계 크리즘은 점토와 탄산염처럼 물이 만든 광물을 찾아 옛 화성이 젖어 있었다는 증거를 쌓았습니다. 그림자 속에서 봄마다 길어지는 검은 줄무늬는 소금물이 흐르는 것일 수 있다고 보았지만, 지금은 마른 모래나 먼지의 흐름이라는 쪽으로 기울었습니다. 지금까지 지구로 보낸 자료는 수백 테라비트에 이릅니다. 하이라이즈 사진 한 장은 폭 6km쯤의 땅을 한 번에 담습니다."),
  juno: t("주노에는 레고 인형 셋이 타고 있습니다. 로마 신 유피테르, 그의 아내 유노, 갈릴레오 갈릴레이를 알루미늄으로 만든 것입니다. 2019년에는 대적점의 뿌리가 구름 아래 300 → 500km까지 뻗어 있다고 밝혔고, 2023년 12월과 2024년 2월에는 이오 곁 1,500km쯤까지 다가가 화산을 가까이 찍었습니다. 임무를 늘린 뒤에는 가니메데와 유로파도 지났습니다. 주노는 2025년 9월까지 임무를 이어 갔고, 마이크로파 장치로 대기 깊은 곳의 암모니아가 어떻게 퍼져 있는지도 알아냈습니다."),
  cassini: t("카시니는 2000년 12월 목성을 스쳐 지나며 속도를 얻었고, 토성에는 2004년 7월 1일 닿았습니다. 13년 동안 사진 45만 장 넘게 보내고 타이탄 곁을 127번 지났습니다. 마지막 해 2017년 4월부터는 고리와 토성 사이의 약 2,400km 틈으로 스물두 번 뛰어드는 마지막 곡예를 했고, 그동안 고리의 무게와 토성의 중력장을 처음 가까이서 쟀습니다. 이 일은 미국, 유럽, 이탈리아가 함께 했습니다. 카시니가 모은 과학 자료는 약 635기가바이트입니다."),
  parker: t("파커는 2021년 4월 태양 바깥 대기 코로나 안으로 들어간 첫 탐사선이 되었습니다. 태양에서 약 1,300만km까지 다가갔을 때 태양의 자기장이 태양풍을 붙잡아 두는 경계를 넘어선 것입니다. 또 자기장이 지그재그로 꺾이는 스위치백이 곳곳에 있는 것을 찾았습니다. 발사에는 델타 4 헤비 로켓이 쓰였고, 91세였던 유진 파커는 발사를 직접 지켜보았습니다. 파커의 장치 네 개는 태양풍의 입자, 전기장과 자기장, 햇빛이 흩어진 모습을 측정합니다."),
  roadster: t("로드스터는 팰컨 헤비의 첫 발사에 실려 케네디 우주센터에서 올라갔고, 차 안에서는 데이비드 보위의 노래 Space Oddity가 되풀이해 흐른다고 머스크가 밝혔습니다. 계기판에는 은하수를 여행하는 히치하이커를 위한 안내서의 문구 Don't Panic이 적혀 있고, 회로 기판에는 Made on Earth by humans라는 글이 새겨져 있습니다. 차의 무게는 약 1,250kg입니다. 2020년 10월에는 화성 궤도를 지나며 화성에서 약 740만km 곁까지 갔습니다. 발사 때는 쌍둥이 보조 로켓 둘이 케이프커내버럴에 동시에 내려앉는 모습도 중계되었습니다."),
  newHorizons: t("2007년 2월 28일 목성 곁을 지나며 중력으로 속도를 초속 4km 더 얻어 명왕성까지 가는 길을 3년 줄였습니다. 명왕성은 지름 약 2,377km로 재어졌고, 푸른 안개가 겹겹이 낀 하늘과 질소 얼음이 흐르는 평원이 드러났습니다. 명왕성의 작은 위성 닉스와 히드라는 탐사선이 떠나기 전해에 허블이 찾았고, 탐사선은 지금 태양에서 60AU 넘게 떨어진 곳을 날고 있습니다. 무게는 약 478kg이고, 플루토늄 전지가 전기를 댑니다."),
  pioneer10: t("금속판은 칼 세이건과 프랭크 드레이크가 설계하고 린다 세이건이 그림을 그렸습니다. 판에는 수소 원자의 모습과 펄서 열네 개의 방향이 새겨져 있어, 어디서 언제 보냈는지 알 수 있게 했습니다. 1983년 6월 13일에는 해왕성 궤도를 지나 행성들의 영역을 벗어난 첫 탐사선이 되었고, 1998년 2월 보이저 1호에 가장 먼 탐사선 자리를 넘겨주었습니다. 탐사선 무게는 258kg에 지나지 않았고, 플루토늄 전지가 내는 전기는 약 155와트에서 시작해 점점 줄었습니다."),
  danuri: t("다누리는 한국항공우주연구원이 만들었고 무게는 약 678kg입니다. 여섯 번째 장치는 우주에서 인터넷처럼 자료를 주고받는 시험 장치로, 2022년 9월 이것으로 방탄소년단의 다이너마이트 영상을 달 궤도에서 지구로 보냈습니다. 한국은 다누리 다음으로 2032년 달 착륙선을 보낼 계획입니다. 다누리가 찍는 극지방의 사진은 그 착륙 자리를 고르는 데도 쓰일 것입니다. 2022년 12월 17일 달 궤도에 들어섰고, 100km 높이에서는 한 바퀴를 약 2시간에 돌았습니다."),
  lro: t("LRO는 2009년 6월 18일 엘크로스 탐사선과 같은 로켓에 실려 올랐습니다. 엘크로스의 로켓 윗단이 10월 9일 남극 가까운 카베우스 충돌구에 부딪쳐 일으킨 먼지 기둥에서 물이 찾아졌습니다. 2019년 12월에는 LRO의 사진 속에서 인도의 착륙선 비크람이 추락한 자리를 한 시민이 찾아냈고, NASA가 이를 확인했습니다. LRO의 레이저 고도계는 수십억 번 높이를 재어 달의 높낮이 지도를 만들었습니다. 중성자 장치와 온도 측정기는 극지방의 그늘진 구덩이 가운데 물 얼음이 있을 만한 곳을 가려냈습니다."),
  europaClipper: t("유로파의 얼음 껍질 아래 바다는 물의 양이 지구의 모든 바다를 합친 것의 두 배가 넘는 것으로 봅니다. 클리퍼는 2025년 3월 화성 곁을 지났고 2026년 12월 지구 곁을 다시 지납니다. 탑재 장치 곁 금속판에는 미국 시인 에이다 리몬이 쓴 시와 260만 명의 이름이 새겨져 있습니다. 유럽우주국의 주스 탐사선도 2031년 목성에 도착해 가니메데 등을 살핍니다. 얼음 틈에서 물기둥이 솟는 일이 있는지도 살피고, 솟는다면 지나가며 그 안의 입자를 모아 분석합니다."),
  lucy: t("루시가 2023년 11월 1일 처음 지난 소행성 딩키네시에서 발견된 위성 셀람은 작은 두 덩이가 붙은 모양이었습니다. 딩키네시는 에티오피아 말로 놀랍다는 뜻이며, 루시 화석의 에티오피아 이름이기도 합니다. 2025년 4월에는 화석을 찾은 도널드 조핸슨의 이름을 딴 소행성을 지나갔습니다. 화석 이름은 발굴 현장에서 비틀스의 노래 루시 인 더 스카이 위드 다이아몬즈를 들었다는 데서 왔습니다. 루시가 나르는 금속판에는 칼 세이건, 비틀스, 마틴 루서 킹 목사 같은 사람들의 글이 새겨져 있습니다."),
  pioneer11: t("1973년 4월 6일 떠났고 1974년 12월 목성에서 처음으로 극지방을 가까이 찍었습니다. 1979년 9월 1일에는 토성 구름 위 약 2만 1,000km까지 다가가 고리 면을 지나며 토성의 자기장을 재고, 타이탄의 온도가 영하 180도쯤으로 생명이 살기에는 너무 차다는 것을 알렸습니다. 마지막 교신은 1995년 9월이었습니다. 토성에서 얻은 자료는 뒤따른 보이저의 길을 고르는 데 쓰였습니다. 토성 고리 면을 지날 때 먼지에 부딪칠까 걱정했으나 탐사선은 무사했습니다."),
  bepiColombo: t("2021년 10월 첫 수성 스침에서는 표면 200km 높이까지 다가가 사진을 보냈습니다. 발사 때 무게는 약 4,100kg이며, 수성까지 데려다주는 추진 모듈이 두 궤도선에 붙어 있다가 수성에 닿기 전에 떨어져 나갑니다. 2024년 4월 이온 엔진의 전력에 문제가 생겨 힘이 줄었고, 그 탓에 도착이 2025년 12월에서 2026년 11월로 한 해 가까이 늦춰졌습니다. 수성에 가는 탐사선으로는 유럽의 첫 번째입니다. 수성 궤도에 든 뒤 처음 계획한 관측 기간은 1년이고, 한 해 더 늘릴 수 있습니다."),
  akatsuki: t("같은 로켓에는 태양 빛을 돛처럼 받아 나아가는 실험기 이카로스도 실려 있었습니다. 2010년 12월 엔진이 꺼진 까닭은 헬륨 가스가 지나가는 밸브가 막힌 것으로 밝혀졌습니다. 처음 계획은 30시간에 한 바퀴 도는 궤도였으나, 엔진 상태 때문에 2016년 4월 10일 남짓에 한 바퀴 도는 길쭉한 궤도로 바꾸어 일을 이어 갔습니다. 발사 전 이름은 플래닛 C였고, 무게는 약 500kg입니다. 금성은 새벽하늘의 샛별로 불려 왔기에 새벽이라는 이름을 붙였습니다."),
  mangalyaan: t("2012년 8월 계획이 승인된 뒤 15개월 만에 만들어 떠났습니다. 무게는 연료를 포함해 1,337kg이고, 컬러 카메라와 메탄을 찾는 장치 등 과학 장치 다섯 개를 실었습니다. 2022년에는 일식이 길게 이어져 햇빛을 받지 못한 전지가 다 닳았고, 이것이 교신이 끊긴 까닭으로 알려져 있습니다. 인도는 이 일로 아시아에서 처음 화성 궤도에 든 나라가 되었습니다. 2015년에는 찍은 사진을 모아 화성 지도책도 펴냈습니다."),
  dawn: t("베스타에는 폭 500km쯤의 거대한 충돌 구덩이가 남극 쪽에 있고, 그 가운데 봉우리는 높이가 약 22km에 이릅니다. 세레스는 지름 약 940km로 소행성대에서 가장 큰 천체이고, 높이 약 4km의 얼음 화산 아후나 몬스도 찾았습니다. 지구에 떨어지는 운석 가운데 일부가 베스타에서 왔다는 것도 돈이 확인했습니다. 돈은 델타 2 로켓에 실려 떠났고 무게는 약 1,200kg입니다. 세레스의 오카토 분화구는 지름이 약 92km이고, 밝은 점들이 그 안에 있습니다."),
  juice: t("2024년 8월 19일과 20일에는 달과 지구를 하루 사이에 잇달아 스쳤는데, 이런 연속 비행은 처음 해 본 것입니다. 얼음 속을 보는 레이더의 안테나는 길이가 16m이고, 자기장을 재는 장치는 10.6m 팔 끝에 달려 있습니다. 목성의 위성들을 살피는 계획으로는 앞서 2024년 10월에 떠난 미국의 유로파 클리퍼와 서로 짝을 이룹니다. 관측 장치는 모두 열 가지입니다. 발사 때 무게는 약 6,100kg이고, 가니메데를 돌면서 얼음의 두께와 바다의 깊이를 잴 예정입니다."),
  hayabusa2: t("류구는 1999년 미국의 린컨 근지구 소행성 탐사 팀이 찾았고, 이름은 우라시마 타로 옛이야기에 나오는 바닷속 용궁에서 땄습니다. 탐사선은 작은 탐사 로버 둘과 독일과 프랑스가 만든 착륙기 마스콧을 내려보냈고, 마스콧은 약 17시간 동안 일했습니다. 앞선 하야부사 1호는 2010년 이토카와의 흙을 가져와, 소행성의 흙을 지구에 가져온 첫 탐사선이 되었습니다. 류구는 밀도가 물의 약 1.2배로, 속에 빈틈이 많은 돌무더기입니다. 캡슐은 호주의 우메라 사막에 내렸습니다."),
  soho: t("소호는 지구에서 약 150만km 떨어진 곳에서 태양을 살핍니다. 태양 속에서 일어나는 소리 같은 떨림을 재어, 태양의 안쪽 모습과 지구 반대편 면의 활동까지 알아냈습니다. 코로나에서 뿜어져 나온 거대한 가스 덩어리가 지구로 향하는지도 지켜봐, 하루에서 사흘 앞서 우주 날씨를 알리는 데 쓰입니다. 발사 때 무게는 약 1,850kg이고 과학 장치 열두 가지를 실었습니다. 소호가 찍은 사진은 누구나 인터넷에서 곧바로 볼 수 있습니다."),
  solarOrbiter: t("2020년 첫 사진에서 태양 표면 곳곳에 아주 작은 폭발이 반짝이는 것을 찾았고, 모닥불이라는 뜻의 캠프파이어라는 이름을 붙였습니다. 크기는 400에서 4,000km쯤입니다. 방패는 티타늄 판에 검은 칼슘 인산염을 입혀 만들었고, 열을 받아 벗겨지거나 먼지가 날리지 않도록 했습니다. 카메라와 장치는 모두 열 가지입니다. 아틀라스 5 로켓으로 케이프커내버럴에서 떠났고 무게는 약 1,800kg입니다. 2022년 3월에는 태양과 지구 사이 거리의 약 3분의 1까지 다가갔습니다."),
  tianwen1: t("탐사차 이름 주룽은 중국 신화의 불의 신에서 왔습니다. 무게는 약 240kg이고 태양전지로 움직입니다. 화성의 하루를 솔이라 하는데, 계획은 90솔이었지만 347솔 동안 일했습니다. 이 탐사선의 뒤를 이어 중국은 2025년 5월 소행성 카모오알레바로 가는 톈원 2호를 쏘아 올렸습니다. 창정 5호 로켓으로 하이난섬의 원창에서 떠났습니다. 주룽이 본 모래 언덕에서는 물이 스친 흔적이 있는 단단한 껍질을 찾았다는 연구가 나왔습니다."),
  osirisRex: t("탐사선 이름은 기원, 분광 해석, 자원 확인, 안전, 표면 탐사를 뜻하는 영어 머리글자를 이은 것입니다. 베누라는 이름은 2013년 아홉 살 학생이 공모에서 지어 뽑혔습니다. 2019년 1월에는 베누의 표면에서 돌 알갱이가 튀어 오르는 것을 처음 보았습니다. 베누는 2182년 9월 24일 지구에 부딪힐 확률이 약 2,700분의 1로 계산됩니다. 발사는 아틀라스 5 로켓으로 케이프커내버럴에서 했습니다. 소행성에서 흙을 가져온 것은 미국으로서는 처음 있는 일입니다."),
  hera: t("디디모스는 지름 약 780m, 디모르포스는 약 160m입니다. 헤라는 팰컨 9 로켓으로 떠났고, 무게가 약 1,100kg입니다. 데려가는 작은 위성 둘은 이탈리아의 밀라니와 룩셈부르크의 유벤타스로, 하나는 자세히 찍고 하나는 땅속을 레이더로 살핍니다. 헤라가 디모르포스의 무게를 재면, 다트가 얼마나 세게 밀었는지 정확히 계산할 수 있습니다. 이름은 그리스 신화에서 결혼의 여신입니다. 다트가 부딪힌 뒤 디모르포스에서는 먼지 꼬리가 몇 달 동안 이어졌고, 허블 우주망원경이 그것을 찍었습니다."),
  tess: t("테스가 처음 찾은 행성은 2018년 9월 발표된 지구에서 약 60광년 떨어진 별 둘레의 파이 멘사이 c입니다. 2020년에는 지구의 1.2배 크기이고 물이 액체로 있을 수 있는 거리를 도는 TOI-700 d를 찾았습니다. 별까지의 거리는 100광년 남짓입니다. 행성뿐 아니라 터지는 별과 혜성의 밝기 변화도 함께 기록합니다. 네 대가 이어 붙인 시야는 가로 24도, 세로 96도의 띠입니다. 팰컨 9 로켓으로 떠났고, 처음 임무 기간은 두 해로 잡았습니다."),
  gaia: t("가이아는 소유스 로켓에 실려 떠났고, 6시간에 한 바퀴씩 천천히 돌면서 하늘을 훑었습니다. 망원경 거울은 탄화규소라는 단단한 세라믹으로 만들어 온도가 바뀌어도 모양이 변하지 않습니다. 앞서 낸 별 목록은 2016년과 2018년, 2022년에 나왔고, 다음 목록은 빠르면 2026년 12월에 나올 예정입니다. 카메라는 하나가 아니라 106개의 센서를 이어 붙인 것입니다. 과학 관측은 2014년 7월에 시작되었습니다."),
  psyche: t("프시케를 이끄는 연구 책임자는 애리조나 주립대의 린디 엘킨스-탠턴입니다. 소행성에 닿으면 높이를 바꿔 가며 도는데, 700km에서 시작해 290km, 190km로 내려가 마지막에는 약 75km까지 낮춥니다. 장치는 카메라, 감마선과 중성자를 재는 분광기, 자기장 측정기 세 가지입니다. 16 프시케는 소행성대 전체 질량의 1%쯤을 차지한다고 봅니다. 발사 때 무게는 약 2,600kg입니다. 소행성에 내려앉지 않고 둘레를 돌며 살피기만 합니다."),
  rosettaCraft: t("이름은 이집트 상형문자를 풀어낸 로제타석에서 땄습니다. 혜성이 태양계의 기원을 푸는 열쇠라는 뜻입니다. 로제타는 2011년 6월부터 2014년 1월까지 957일 동안 전기를 아끼려고 잠을 잤습니다. 착륙선 필레는 세 번 튕긴 끝에 절벽 그늘에 비스듬히 서서 햇빛을 못 받았고, 전지로 약 64시간 일한 뒤 멈췄습니다. 필레의 위치는 2016년 9월 2일에야 사진에서 찾았습니다. 추류모프-게라시멘코는 오리 같은 모양이고 길이가 약 4km입니다. 이 혜성은 2015년 8월 태양에 가장 가까이 다가갔습니다."),
  galileoCraft: t("목성의 고리는 작은 위성들에서 떨어져 나온 먼지로 이루어졌다는 것을 갈릴레오가 밝혔습니다. 2002년 11월에는 안쪽 위성 아말테아 160km 곁을 지났는데, 이 위성은 밀도가 물보다 낮아 돌무더기에 가깝습니다. 목성 대기에 뛰어든 탐사체는 예상보다 물이 적다는 것과 시속 약 640km의 강한 바람이 깊이까지 이어진다는 것을 알렸습니다. 목성의 강한 방사선 때문에 장치가 여러 번 이상을 일으켰지만, 갈릴레오는 계획보다 길게 8년 넘게 일했습니다."),
  messengerCraft: t("메신저는 12시간에 한 바퀴 도는 길쭉한 궤도로 수성의 가까운 곳은 200km, 먼 곳은 약 15,000km 떨어져 돌았습니다. 수성의 자기장 중심이 행성 중심에서 북쪽으로 480km쯤 치우쳐 있다는 것을 밝혔고, 속에 든 금속 핵이 반지름의 약 85%로 아주 크다는 것도 알아냈습니다. 수성을 4,000바퀴 넘게 돌았고, 새로 찾은 분화구에는 예술가의 이름이 붙습니다. 수성 땅 전체를 처음으로 빠짐없이 지도로 만든 것은 2013년 3월입니다. 지도가 완성된 것은 임무를 두 번 늘린 덕분입니다."),
  apollo11: t("사령관은 닐 암스트롱이고 사령선 조종사는 마이클 콜린스였습니다. 아폴로 11호는 7월 16일 새턴 5호 로켓으로 케네디 우주센터에서 떠났고, 7월 24일 태평양에 내렸습니다. 달 표면 장면은 약 6억 명이 텔레비전으로 보았다고 합니다. 돌아온 세 사람은 달의 병균을 걱정해 21일 동안 격리되었습니다. 달에는 모든 인류를 위해 평화롭게 왔다는 글을 새긴 판이 남아 있습니다. 여행은 모두 8일 3시간쯤 걸렸습니다. 이글이라는 이름은 미국을 상징하는 흰머리수리에서 따왔습니다."),
  viking1: t("착륙선은 1982년 토머스 머치 기념 기지라는 이름을 받았습니다. 영상팀 책임자였던 머치가 1980년 산에서 사고로 숨졌기 때문입니다. 착륙 닷새 뒤인 7월 25일 궤도선은 화성의 시도니아 지역에서 사람 얼굴처럼 보이는 언덕을 찍었는데, 훗날 더 선명한 사진으로 평범한 언덕임이 확인되었습니다. 첫 컬러 사진 속 화성의 하늘은 먼지 때문에 분홍빛이었습니다. 착륙선의 무게는 약 576kg입니다. 날씨를 재는 장치로 6년 동안 화성의 기온과 바람을 쟀습니다."),
  huygens: t("하위헌스는 무게 318kg, 너비 2.7m의 둥근 탐사체입니다. 2004년 12월 25일 카시니에서 떨어져 20일쯤 혼자 날았습니다. 타이탄 대기에는 초속 약 6km로 들어갔고, 불타는 열을 견디는 방패로 속도를 줄인 뒤 낙하산을 폈습니다. 내려앉을 때 얇은 껍질 아래 무른 땅이라는 신호가 잡혔고, 땅에서 메탄이 스며 나오는 것도 알아냈습니다. 지구에서는 전파망원경들이 하위헌스의 신호를 따로 받아 내린 자리를 확인했습니다. 내려앉은 곳은 밝은 땅 아디리 가까이였습니다."),
  "place:cassini": t("카시니는 1997년 10월 15일 타이탄 4B 로켓으로 떠났고, 7년을 날아 2004년 7월 토성 둘레에 들었습니다. 이름은 1675년 토성 고리 사이의 틈을 찾은 이탈리아 태생의 천문학자 조반니 카시니에서 왔습니다. 2013년 7월에는 토성의 그림자 속에서 고리 너머 멀리 있는 지구를 찍었습니다. 위성도 여러 개 새로 찾아냈습니다. 그 틈은 카시니 간극이라 부르며 너비가 약 4,800km입니다. 카시니가 있는 동안 토성의 계절이 한 번 바뀌는 것도 지켜보았습니다."),
  "place:newHorizons": t("뉴허라이즌스는 초속 약 16km로 지구를 떠나, 인류가 쏘아 올린 물체 가운데 가장 빠른 출발 기록을 세웠습니다. 2007년 2월 목성 곁을 지나며 중력으로 속도를 더 얻어 명왕성 도착을 3년 앞당겼습니다. 명왕성을 찾은 클라이드 톰보의 재 일부가 탐사선에 실려 있고, 명왕성의 하트 모양 땅은 그의 이름을 따 톰보 지역이라 부릅니다. 탐사선은 피아노만 한 크기이고 무게는 약 478kg입니다. 태양에서 멀어 전기는 플루토늄의 열로 만듭니다."),
  giotto: t("지오토는 1985년 7월 2일 아리안 1 로켓으로 떠났고, 유럽우주국이 처음으로 쏘아 올린 우주 깊은 곳 탐사선입니다. 핼리 혜성과는 초속 약 68km로 마주쳤습니다. 먼지 알갱이가 총알보다 빠르게 날아오기 때문에 앞쪽에 얇은 방패를 겹쳐 달았습니다. 혜성의 먼지에는 탄소가 많은 알갱이가 가득했고, 그 속에서 생명의 재료가 되는 가벼운 원소들이 나왔습니다. 가장 가까이 지날 때 부딪힌 먼지 때문에 탐사선이 흔들려 교신이 32분쯤 끊겼다가 돌아왔습니다."),
  "place:voyager1": t("1979년 3월 보이저 1호가 찍은 사진에서 린다 모라비토가 이오 가장자리에 솟은 화산 기둥을 찾았습니다. 태양계에서 지구 밖 화산이 터지는 모습을 처음 본 것입니다. 보이저 1호는 1980년 타이탄 곁을 지나면서 궤도가 행성들이 놓인 판 밖으로 휘어졌습니다. 2023년 11월 컴퓨터 기억장치 고장으로 뜻 모를 신호를 보냈으나, 2024년 4월 지구에서 고쳤습니다. 무게는 약 825kg입니다. 컴퓨터의 기억 용량은 약 69KB로, 요즘 사진 한 장보다 훨씬 작습니다."),
  paleBlueDot: t("세이건이 카메라를 돌려 달라고 졸랐을 때 이를 받아들인 사람은 당시 나사 국장이던 리처드 트룰리였습니다. 세이건은 1994년 이 사진을 이름으로 삼은 책 창백한 푸른 점을 냈습니다. 사진을 찍은 뒤 보이저 1호의 카메라를 다시 켜지 못하도록 관련 프로그램도 지워졌습니다. 이 사진 속 점이 태양계 끝에서 본 우리 집입니다. 이 사진은 지구가 있는 평면에서 위로 32도쯤 올라간 곳에서 찍었습니다. 지구까지 빛이 닿는 데 5시간 반쯤 걸리는 거리였습니다."),
  dokdo: t("독도의 면적은 187,554제곱미터로, 축구장 26개쯤의 넓이입니다. 1982년 천연기념물 제336호로 지정되었습니다. 바위틈에는 섬기린초와 해국 같은 바닷가 식물이 자라고, 나무는 거의 없습니다. 동도와 서도 사이는 약 150m 떨어져 있습니다. 독립문바위와 천장굴 같은 바위 지형은 파도와 바람이 오랫동안 깎아 만들었습니다. 바닷속에서 잰 섬의 높이는 2,000m가 넘습니다. 서도에는 물이 솟는 샘 물골이 있어 사람이 마실 수 있습니다."),
  luna2: t("루나 2호는 1959년 9월 12일 떠나 약 34시간을 날았고 무게는 약 390kg입니다. 부딪힌 곳은 아리스타르코스, 아르키메데스, 아우톨리쿠스 분화구가 모인 곳 가까이였습니다. 달에는 지구 같은 방사선대가 없다는 것도 가는 길에 확인했고, 태양에서 불어 오는 바람인 태양풍을 직접 잰 첫 탐사선 가운데 하나입니다. 흐루쇼프는 방문한 미국에서 표지 복제품을 아이젠하워에게 선물했습니다. 영국 조드럴 뱅크 천문대가 루나 2호의 전파를 쫓아 충돌 시각을 확인했습니다."),
  luna9: t("루나 9호는 1966년 1월 31일 떠나 나흘 뒤 내렸고, 달에 닿은 시각은 2월 3일 18시 45분(세계시)이었습니다. 내린 곳은 라이너와 마리우스 분화구 근처입니다. 사진은 일곱 번에 걸쳐 모두 8시간 남짓 보냈습니다. 앞서 소련은 달 착륙에 열한 번 실패했으니, 루나 9호는 열두 번째 시도에서 성공한 것입니다. 사진에는 작은 돌과 가는 알갱이가 흩어진 땅이 담겼습니다. 넉 달 뒤인 6월에는 미국의 서베이어 1호가 달에 내렸습니다. 루나 9호는 무게가 1,538kg이고, 달에 놓인 캡슐은 그 가운데 100kg쯤입니다."),
  surveyor1: t("서베이어 1호는 1966년 5월 30일 아틀라스-센타우르 로켓으로 떠나 63시간 남짓 만에 달에 닿았습니다. 달에 내린 뒤 무게는 약 294kg이었습니다. 첫 사진은 착륙 몇 분 뒤에 도착했습니다. 달의 밤 두 주를 지나고도 깨어나 일했으며, 마지막 교신은 1967년 1월입니다. 2009년 달 정찰 궤도선이 착륙선 자리를 위에서 찍었습니다. 내린 곳은 플램스티드 P라는 오래된 분화구 안쪽입니다. 카메라를 돌려 360도 파노라마를 찍었고, 첫 낮에만 1만 장 남짓을 보냈으며 밤을 넘긴 뒤에도 800장 남짓을 더 보냈습니다. 서베이어 1호는 휴즈 항공기가 만들었고 운영은 나사 제트추진연구소가 맡았습니다."),
  surveyor7: t("알파 입자를 쏘아 흙의 성분을 재는 장치가 처음에는 땅에 내려오지 않았는데, 지구에서 로봇 팔로 눌러 주어 쓸 수 있었습니다. 잰 결과 고지대 흙은 바다 지역보다 철이 적고 알루미늄이 많았습니다. 그래서 고지대가 더 가벼운 암석으로 되어 있다고 보게 되었습니다. 서베이어 7호는 두 번째 달의 밤을 지나고 1968년 2월 교신이 끊겼습니다. 1월 7일 아틀라스-센타우르 로켓으로 떠나 사흘 만에 닿았습니다. 내린 곳은 티코 가장자리에서 북쪽으로 약 29km인데, 티코에서 뻗은 밝은 줄무늬는 지구에서 보이는 달의 줄무늬 가운데 가장 뚜렷한 것으로 꼽힙니다."),
  apollo12: t("사령관 피트 콘래드, 달 착륙선 조종사 앨런 빈, 사령선 조종사 리처드 고든이 탔습니다. 착륙선 이름은 인트레피드이고 사령선은 양키 클리퍼였습니다. 두 사람은 돌과 흙 34kg쯤을 가져왔고, 원자력 전지로 움직이는 관측 장치 묶음을 놓고 왔습니다. 그 장치는 1977년까지 일했습니다. 떠난 착륙선의 윗부분을 달에 부딪히자, 달이 한 시간 가까이 종처럼 울렸습니다. 발사는 11월 14일 케네디 우주센터에서 했습니다."),
  luna16: t("루나 16호는 1970년 9월 12일 떠났습니다. 달에 머문 시간은 26시간쯤이고, 땅에서 올라간 윗부분은 작은 귀환 캡슐을 달고 돌아왔습니다. 내린 곳은 풍요의 바다에 있는 웹 분화구 근처였습니다. 가져온 흙은 짙은 회색의 고운 알갱이였고 현무암 성분이었습니다. 1969년 7월 아폴로 11호와 겨루려던 루나 15호는 달에 부딪혀 실패했습니다. 지구 밖 다른 천체에서 로봇이 스스로 날아오른 것도 이것이 처음입니다. 캡슐은 9월 24일 카자흐스탄의 제즈카즈간 남동쪽 약 80km에 내렸고, 착륙기의 아랫부분은 지금도 풍요의 바다에 남아 있습니다."),
  lunokhod1: t("루노호트 1호는 달의 낮 사흘, 곧 석 달쯤만 일하도록 설계되었는데 열한 번의 달 낮을 버텼습니다. 네 대의 텔레비전 카메라로 길과 땅을 비추었고, 흙의 성분과 단단함을 25곳에서 쟀습니다. 등의 레이저 반사경은 프랑스가 만들었습니다. 마지막 교신은 1971년 9월이고, 열이 모자라 밤을 넘기지 못한 것으로 봅니다. 루나 17호는 1970년 11월 10일 프로톤 로켓으로 떠났습니다. 탐사차는 욕조 같은 몸체에 둥근 뚜껑이 달린 모양이고, 바퀴 여덟 개마다 모터가 따로 있어 하나가 고장 나도 달릴 수 있었습니다."),
  apollo14: t("승무원은 앨런 셰퍼드, 에드거 미첼, 스튜어트 루사입니다. 달로 가는 길에 사령선과 착륙선이 도킹에 여섯 번 만에 성공했습니다. 착륙 직전에는 중단 스위치가 잘못 켜졌는데, 지상팀이 프로그램을 고쳐 보내 내릴 수 있었습니다. 두 사람이 가져온 돌 가운데 가장 큰 것은 약 9kg이고, 빅 버사라는 이름이 붙었습니다. 1971년 1월 31일 케네디 우주센터에서 떠났습니다. 달 표면에 머문 시간은 33시간 반쯤입니다."),
  apollo15: t("승무원은 데이비드 스콧, 제임스 어윈, 앨프리드 워든입니다. 두 사람은 달에 66시간 55분 머물며 세 번 밖으로 나가 모두 18시간 반쯤 일했고, 돌과 흙 77kg을 가져왔습니다. 창세기의 돌은 나이가 40억 년이 넘는 것으로 밝혀졌습니다. 돌아올 때 낙하산 셋 가운데 하나가 펴지지 않았지만 둘로도 무사히 바다에 내렸습니다. 1971년 7월 26일에 떠났습니다. 스콧은 달 궤도에 작은 위성 하나를 남겨 두고 돌아왔습니다."),
  apollo16: t("승무원은 존 영, 찰스 듀크, 켄 매팅리입니다. 두 사람은 달에 71시간쯤 머물렀고, 월면차를 시속 약 17km까지 몰아 달 위의 속도 기록을 세웠습니다. 가져온 돌 가운데 가장 큰 것은 11.7kg으로, 아폴로가 가져온 돌 중 가장 크고 빅 뮬리라는 이름이 붙었습니다. 존 영은 훗날 1981년 첫 우주왕복선 컬럼비아호를 몰았습니다. 존 영은 우주에 여섯 번 나간 사람으로 제미니 3호에도 탔습니다. 아폴로 16호는 1972년 4월 16일 떠났는데, 사령선 조종사 켄 매팅리는 아폴로 13호 때 풍진에 걸릴 염려로 빠졌다가 이번에 탔습니다. 사령선 이름은 캐스퍼, 착륙선 이름은 오리온입니다."),
  apollo17: t("아폴로 17호는 1972년 12월 7일 한밤중에 떠났고, 새턴 5호가 밤에 발사된 첫 임무였습니다. 이것이 새턴 5호의 마지막 달 비행입니다. 두 사람은 달에 약 75시간 머물렀고, 사령선 조종사 로널드 에번스는 혼자 달을 돌았습니다. 슈미트는 훗날 미국 상원의원이 되어 뉴멕시코주를 대표했습니다. 달을 걸은 사람은 이로써 모두 열두 명입니다. 가져온 돌과 흙은 110.5kg으로 아폴로 임무 가운데 가장 많습니다. 착륙선 이름은 챌린저, 사령선 이름은 아메리카였습니다."),
  lunokhod2: t("루나 21호는 1973년 1월 8일 프로톤 로켓으로 떠나 15일에 내렸습니다. 루노호트 2호는 파노라마 사진 86장과 텔레비전 사진 8만 장 넘게 보냈습니다. 흙을 재고, 자기장을 재는 장치와 하늘의 밝기를 재는 장치도 실었습니다. 달에 있는 갈라진 골짜기도 건너 달렸습니다. 마지막 교신은 1973년 5월입니다. 르모니에 분화구는 맑음의 바다와 타우루스 산지 사이에 있어 바다와 고지의 경계를 살피려고 고른 곳입니다. 이 탐사차도 프랑스가 만든 레이저 반사경을 달았습니다."),
  luna24: t("루나 24호는 1976년 8월 9일 발사되어 8월 18일 달에 내렸습니다. 땅을 파는 드릴이 달린 팔이 흙을 길쭉한 관에 담았고, 관은 둘둘 말아 귀환 캡슐에 넣었습니다. 캡슐은 8월 22일 시베리아의 수르구트 남동쪽에 떨어졌습니다. 관에 든 흙은 층이 나뉜 채 보존되어 달 표면 아래의 층 구조를 볼 수 있었습니다. 소련과 미국은 서로의 달 시료 일부를 나누어 연구했습니다. 소련은 루나 16호(1970년), 20호(1972년), 24호로 모두 세 번 달의 흙을 가져왔고, 합치면 약 330g입니다. 아폴로가 여섯 번 가져온 382kg에 비하면 아주 적은 양입니다."),
  change3: t("창어 3호는 2013년 12월 2일 쓰촨성 시창에서 발사되어 열이틀 뒤 달에 내렸습니다. 내려오던 중 달 위 100m에서 잠시 멈춰 카메라와 레이저로 바닥을 살피고 돌이 없는 자리를 골랐습니다. 탐사차의 이름 위투는 인터넷 투표로 정했습니다. 무게는 140kg이고, 두 번째 달의 밤을 앞둔 2014년 1월 기계 장치에 문제가 생겨 더는 제대로 달리지 못했습니다. 위투는 2016년 8월에 임무를 끝냈습니다. 중국의 달 탐사는 돌기, 내리기, 돌아오기의 세 단계로 짜여 있고, 창어 1호(2007년)와 2호(2010년)가 돌기 단계를, 창어 3호가 내리기 단계를 맡았습니다."),
  change4: t("창어 4호보다 앞선 2018년 5월, 중계 위성 췌차오가 달 뒤쪽 약 6만 5천 km의 라그랑주 점 둘레 궤도에 올랐습니다. 착륙선은 2018년 12월 8일 발사되어 한 달 가까이 걸려 내렸습니다. 위투 2호는 2019년 네이처에 실린 연구에서 달의 맨틀에서 온 것으로 보이는 광물을 찾았다고 밝혔습니다. 또 루노호트 1호가 세운 약 11개월의 기록을 넘어 달 위에서 가장 오래 일한 탐사차가 됐습니다. 독일의 방사선 측정기도 실려 있었습니다. 통에는 목화씨 말고도 감자, 유채, 애기장대 씨앗과 효모, 초파리 알도 들어 있었습니다. 달의 낮 하루는 지구의 2주쯤이어서 위투 2호는 낮에 일하고 밤에는 잠들었다 깨기를 되풀이했습니다."),
  change5: t("창어 5호는 2020년 11월 23일 하이난섬의 원창에서 창정 5호 로켓에 실려 올랐습니다. 착륙선은 2m 깊이까지 파는 드릴과 흙을 뜨는 삽으로 시료를 모았고, 이틀가량 달 위에서 일했습니다. 흙을 실은 상승선은 12월 3일 달에서 떠올랐는데, 중국이 달에서 이륙시킨 첫 사례입니다. 천으로 만든 오성홍기도 달 위에서 펼쳐 보였습니다. 2022년에는 이 시료에서 새 광물 창어석이 발견됐습니다. 탐사선은 궤도선, 귀환선, 착륙선, 상승선의 네 부분으로 이루어져 있었습니다. 귀환 캡슐은 내몽골 초원에 내렸고, 발사에서 귀환까지 24일이 걸렸습니다."),
  chandrayaan3: t("찬드라얀 3호는 2023년 7월 14일 인도 남동쪽 스리하리코타에서 발사되어 40일 만에 내렸습니다. 착륙선 비크람은 임무를 마친 뒤 엔진을 다시 켜 약 40cm 뛰어올랐다가 내렸고, 이는 다음 탐사를 위한 시험이었습니다. 땅속 온도를 잰 장치는 표면이 약 70도일 때 8cm 아래는 영하 10도쯤이라고 알렸습니다. 인도는 착륙한 8월 23일을 우주의 날로 정했습니다. 찬드라얀은 산스크리트어로 달 탈것이라는 뜻입니다. 비크람은 인도 우주 개발의 아버지 비크람 사라바이에서, 프라그얀은 지혜를 뜻하는 말에서 이름을 땄고, 탐사차는 무게가 26kg입니다."),
  slim: t("슬림은 2023년 9월 7일 다네가시마 우주센터에서 엑스리즘 위성과 함께 발사됐습니다. 내려갈 때는 달의 분화구 모양을 카메라로 알아보고 미리 저장한 지도와 맞춰 제 위치를 알아냈습니다. 착륙 뒤 전지가 12% 남았을 때 일단 전원을 껐고, 여드레 뒤 깨어나 근처 암석을 찍었습니다. 암석에는 토이푸들 같은 개 품종의 이름을 붙였고, 분광 카메라로 감람석 성분을 재었습니다. 슬림은 달을 조사하는 똑똑한 착륙선이라는 뜻의 영어 이름을 줄인 것입니다. 연료를 빼면 약 200kg인 작은 착륙선이고, 발사에서 착륙까지 4개월 넘게 걸렸습니다."),
  odysseus: t("오디세우스는 2024년 2월 15일 팰컨 9 로켓으로 발사됐습니다. 키 4.3m의 육각 기둥 모양이고, 액체 메탄과 액체 산소를 쓰는 엔진으로 내려온 첫 착륙선입니다. 남극에서 약 300km 거리의 남위 80도에 내려, 당시 가장 극에 가까운 착륙 기록이었습니다. NASA의 장비 여섯 개와 민간 실험을 실었고, 교신은 2월 말 태양이 지면서 끝났습니다. 인튜이티브 머신스는 미국 텍사스 주 휴스턴에 있는 회사입니다. 오디세우스에는 미술가 제프 쿤스가 만든 작은 달 조각 125개가 든 작품도 실렸습니다."),
  change6: t("창어 6호는 2024년 5월 3일 원창에서 발사됐고, 앞서 3월에 올린 중계 위성 췌차오 2호가 뒷면과의 교신을 이었습니다. 착륙선은 드릴과 삽으로 흙을 모은 뒤 이틀가량 일했고 6월 4일 달 뒷면에서 처음으로 이륙했습니다. 상승선은 달 궤도에서 궤도선과 만나 시료를 옮겼습니다. 착륙선은 천으로 만든 중국 국기를 뒷면에서 펼쳤습니다. 나중에 분석한 결과 뒷면 맨틀은 앞면보다 물이 적은 것으로 나타났습니다. 귀환 캡슐은 내몽골 쓰쯔왕기에 내렸는데, 창어 5호의 캡슐이 내린 곳과 같은 곳입니다. 착륙한 아폴로 분지는 지름이 약 500km로, 남극-에이트켄 분지 안에 있는 더 작은 충돌 분지입니다."),
  blueGhost: t("블루 고스트라는 이름은 미국 남동부에 사는 반딧불이 한 종에서 왔습니다. 2025년 1월 15일 팰컨 9 로켓에 실려 일본 아이스페이스의 착륙선과 함께 발사됐습니다. 엑스선 카메라 렉시로 지구 둘레의 자기장을 찍었고, 전기로 먼지를 털어 내는 장치와 달 흙이 표면에 붙는 정도를 재는 장치도 시험했습니다. 해가 진 뒤에도 약 네 시간 더 자료를 보냈습니다. 파이어플라이는 미국 텍사스 주에 있는 회사입니다. 블루 고스트는 키 2m, 폭 3.5m의 작은 착륙선으로, NASA의 민간 달 배달 사업에서 세 번째로 달에 간 착륙선입니다. 앞의 둘 중 하나는 달에 닿지 못했고 하나는 쓰러졌습니다."),
  mars3: t("마스 3호는 1971년 5월 28일 발사되어 12월 2일 화성에 닿았습니다. 착륙선은 무게 358kg으로, 궤도에서 떨어져 나와 공기 마찰, 낙하산, 역추진 로켓으로 속도를 줄였습니다. 탐사차 프로프-M은 15m 줄로 착륙선과 이어지게 되어 있었습니다. 같은 해 11월 미국의 마리너 9호가 먼저 화성 궤도에 올라 먼지 폭풍이 걷히기를 기다렸습니다. 마스 3호의 궤도선은 화성 표면 온도를 영하 110도에서 영상 13도로 쟀습니다. 착륙선의 신호는 궤도선이 받아 지구로 중계했습니다."),
  viking2: t("바이킹 2호는 1975년 9월 9일 발사되어 1976년 8월 7일 화성 궤도에 올랐고, 한 달 가까이 착륙지를 살핀 끝에 내렸습니다. 착륙선은 원자력 전지 두 개로 전기를 만들어 오래 버텼고, 1980년 4월 11일 마지막 신호를 보냈습니다. 궤도선은 1977년 10월 화성의 작은 달 데이모스에 약 30km까지 다가가 찍었고, 1978년 7월 자세 조절용 기체가 새 임무를 끝냈습니다. 두 바이킹이 보낸 사진은 합쳐 5만 장이 넘습니다. 착륙선은 생명 실험 세 가지와, 흙의 유기물을 찾는 기체 분석기를 실었습니다. 기체 분석기는 유기물을 찾지 못했고, 이 결과가 생명 실험의 풀이가 갈리는 이유 가운데 하나입니다."),
  pathfinder: t("패스파인더의 설계 수명은 착륙선 30일, 소저너 7일이었는데 모두 몇 배로 넘겼습니다. 착륙선은 1만 6천 장이 넘는 사진을 보냈고 소저너도 약 550장을 찍었습니다. 소저너는 근처 돌에 바너클 빌, 요기 같은 만화 주인공 이름을 붙여 가며 성분을 쟀습니다. 도중에 컴퓨터가 자꾸 멈추는 문제가 생겨, 지구에서 소프트웨어를 고쳐 보냈습니다. 에어백으로 충격을 받아 내리는 방식은 화성에서는 이 임무가 처음 썼고, 뒤에 스피릿과 오퍼튜니티도 이어서 썼습니다."),
  beagle2: t("비글 2호는 영국의 콜린 필린저가 이끌어 만든 33kg짜리 착륙선입니다. 2003년 6월 2일 마스 익스프레스와 함께 발사됐고, 12월 19일 모선에서 떨어져 엿새 뒤 내렸습니다. 착륙을 알리는 신호음은 영국 밴드 블러가 만들었고, 미술가 데이미언 허스트는 색 보정용 판에 색점을 그렸습니다. 2015년 1월 영국 우주국은 비글 2호가 내려앉았지만 태양전지판이 다 펴지지 않았다고 발표했습니다. 비글 2호도 낙하산과 에어백을 써서 내렸습니다."),
  spirit: t("스피릿과 오퍼튜니티라는 이름은 미국 애리조나에 사는 러시아 출신 아홉 살 소피 콜리스가 쓴 글에서 뽑혔습니다. 2004년 1월 착륙 17일 뒤 메모리 문제로 교신이 한때 엉켰으나 고쳤습니다. 2005년 8월에는 높이 약 100m의 허즈번드 언덕 꼭대기에 올랐고, 그 뒤 홈 플레이트라는 둥근 지형에서 화산과 물이 만난 흔적을 찾았습니다. 마지막 교신은 2010년 3월 22일이고, 2011년 5월 25일 공식으로 임무를 마쳤습니다."),
  opportunity: t("오퍼튜니티는 2015년 3월 마라톤 거리 42.195km를 달렸고, 11년 2개월이 걸렸습니다. 2005년에는 퍼거토리 모래언덕에 바퀴가 빠져 다섯 주 넘게 꼼짝 못하다 겨우 빠져나왔습니다. 2011년 엔데버 분화구 가장자리에 닿아 석고가 든 줄무늬 돌을 찾았는데, 석고는 물에서 생기는 광물입니다. 마지막 교신은 2018년 6월 10일이고, 그때까지 일한 날은 5,100솔(화성의 하루)을 넘습니다."),
  phoenix: t("피닉스는 2007년 8월 4일 발사되어 10개월 가까이 날아 내렸고, 에어백이 아닌 역추진 로켓으로 속도를 줄였습니다. 이끈 사람은 애리조나 대학의 피터 스미스로, 대학이 이끈 첫 NASA 화성 탐사입니다. 로봇 팔의 길이는 2.35m이고, 파낸 도랑에는 스노 화이트 같은 이름을 붙였습니다. 흙을 물에 풀어 재어 보니 산성이 아니라 약한 염기성이었고 탄산칼슘도 있었습니다. 화성의 북극 가까운 땅에 내린 첫 탐사선이고, 겨울 햇빛이 모자라 11월 2일 마지막 신호를 보냈습니다."),
  curiosity: t("착륙한 자리는 SF 작가 레이 브래드버리를 기려 브래드버리 착륙지라 부릅니다. 2013년 2월 옐로나이프 만에서 처음으로 화성 돌에 구멍을 뚫어 시료를 얻었고, 점토 광물이 나와 옛 물이 산성이 아니고 소금기도 적었음을 알려 줬습니다. 2018년에는 약 35억 년 된 진흙돌에서 유기 분자를 찾았다고 발표했습니다. 이 탐사차는 높이 5km가 넘는 샤프산을 계속 오르며 지층을 읽고 있습니다. 큐리오시티라는 이름은 미국 캔자스의 열두 살 클라라 마가 쓴 글로 정했습니다."),
  insight: t("인사이트는 2018년 5월 5일 미국 캘리포니아에서 발사되어, 그곳에서 쏘아 올린 첫 행성 탐사선이 됐습니다. 2019년 4월 6일 처음으로 화성 지진을 들었습니다. 가장 큰 지진은 2022년 5월에 일어난 규모 5였습니다. 지진계를 바람과 온도 변화에서 가리려고 둥근 덮개를 씌웠습니다. 로봇 팔로 장비를 흙 위에 직접 내려놓은 것도 다른 행성에서는 처음이었습니다. 이름 인사이트는 지진과 열로 화성의 속을 조사한다는 뜻의 영어 낱말을 줄여 만들었습니다."),
  perseverance: t("퍼서비어런스라는 이름은 버지니아의 중학생 알렉스 매더가 쓴 글로 정했습니다. 2020년 7월 30일 발사됐고, 예제로는 슬라브어로 호수를 뜻합니다. 목시는 모두 16번 가동해 산소 122g을 만들었습니다. 2022년 12월부터 2023년 1월까지는 시료 통 열 개를 한곳에 모아 내려놓아, 다른 행성에 처음 만든 시료 저장소 쓰리 포크스를 남겼습니다. 2024년 7월에는 표범 무늬 같은 얼룩이 있는 돌 치예바 폭포를 찾았습니다."),
  zhurong: t("톈원이라는 이름은 고대 시인 굴원의 시 '천문'에서 왔고, 하늘에 던지는 물음이라는 뜻입니다. 톈원 1호는 2020년 7월 23일 발사되어 2021년 2월 화성 궤도에 올랐고, 착륙은 석 달 뒤였습니다. 주룽은 무게 240kg입니다. 이 탐사차는 모래언덕 껍질에서 물이 들어 있는 광물을 찾았다고 알렸습니다. NASA의 화성 정찰 궤도선은 주룽이 남긴 바퀴 자국과 착륙선의 사진을 찍었습니다. 주룽이라는 이름은 인터넷 투표로 정했습니다. 계획한 90 화성일의 세 배를 넘겨 일했습니다."),
  tycho: t("티코의 이름은 망원경 없이 하늘을 재어 이름난 덴마크 천문학자에서 왔고, 그의 관측 자료를 바탕으로 케플러가 행성 운동의 법칙을 찾았습니다. 1968년 서베이어 7호는 이 근처의 흙을 분석해, 고지대 흙에 알루미늄이 많고 철이 적다는 것을 보여 주었습니다. 소설과 영화 2001 스페이스 오디세이에서는 이 분화구 아래에서 땅에 묻힌 검은 판 모놀리스가 발견됩니다. 분화구의 안쪽 벽은 층층이 무너져 내린 계단 모양이고, 바닥 일부는 충돌로 녹았다 굳은 암석입니다."),
  copernicus: t("달의 지질 시대 가운데 가장 젊은 시대를 이 분화구의 이름을 따 코페르니쿠스기라 부릅니다. 분화구 이름은 1651년 리치올리가 붙였고, 지동설을 담은 책을 1543년 낸 폴란드 천문학자 코페르니쿠스를 기린 것입니다. 가운데 봉우리에서는 달 깊은 곳에서 왔을 것으로 보이는 감람석이 나왔습니다. 분화구가 생길 때 튀어 나간 돌덩이들이 둘레에 줄지어 작은 분화구를 남겼습니다. 코페르니쿠스는 천체의 회전에 관하여라는 책이 나온 1543년에 세상을 떠났습니다. 앞의 루나 오비터 2호 사진은 1966년 11월 23일에 찍혔습니다."),
  tranquillitatis: t("고요의 바다라는 이름은 1651년 리치올리의 달 지도에서 비롯됐습니다. 아폴로 11호의 흙과 돌은 21.5kg이었고, 대부분 36억에서 39억 년 전에 굳은 현무암이어서 달 바다의 나이를 처음 직접 재게 해 주었습니다. 착륙지 근처의 작은 분화구 셋에는 우주비행사의 이름을 따 암스트롱, 올드린, 콜린스라는 이름이 붙었습니다. 착륙한 곳은 고요의 기지라 부릅니다. 아폴로 11호는 1969년 7월 20일에 내려 우주비행사 둘이 밖에서 2시간 반쯤 일했고, 달에는 약 21시간 머물렀습니다. 이들이 남긴 거울은 지금도 지구에서 쏜 레이저를 되돌려 보냅니다."),
  imbrium: t("비의 바다라는 이름은 1651년 리치올리가 붙였습니다. 분지가 생길 때 튀어 나간 물질이 아폴로 14호가 내린 프라마우로 지역을 덮었고, 그곳 돌의 나이로 충돌 시기를 약 38억 년 전으로 어림합니다. 바다 안에는 지름 83km의 아르키메데스 분화구가 있습니다. 이곳은 둘레보다 중력이 센 마스콘으로도 알려져 있습니다. 아폴로 14호는 1971년 2월 5일 프라마우로에 내렸고, 앨런 셰퍼드는 그곳에서 골프공 두 개를 쳤습니다. 바다 북서쪽 가장자리에는 지름 약 250km의 반원 모양 무지개 만이 붙어 있습니다."),
  procellarum: t("폭풍의 대양이라는 이름도 1651년 리치올리가 붙였습니다. 이 땅 밑에는 열을 내는 방사성 원소 토륨이 달의 다른 곳보다 훨씬 많이 모여 있어, 1998년 루나 프로스펙터가 처음 지도로 그렸습니다. 1969년 아폴로 12호는 2년 반 전 내린 서베이어 3호 곁에 내려, 우주비행사가 걸어가 그 카메라와 부품 약 10kg을 지구로 가져왔습니다. 달에서 오래 지낸 기계가 어떻게 변했는지 살피는 자료가 됐습니다."),
  aitken: t("분지의 이름 에이트켄은 미국 천문학자 로버트 에이트켄에서 왔습니다. 1994년 클레멘타인 탐사선의 레이저 자료로 이 거대한 지형의 깊이가 처음 잘 알려졌습니다. 분지는 약 42억 5천만 년 전에 생겼다고 보며, 창어 6호가 가져온 흙은 이 분지 안의 것입니다. 안쪽 바닥은 철과 토륨이 둘레보다 많습니다. 미국 과학자들은 이곳의 시료를 지구로 가져오는 일을 오래전부터 중요한 과제로 꼽아 왔습니다. 깊이 8km는 에베레스트산의 높이에 가까운 값입니다."),
  shackleton: t("섀클턴은 남극-에이트켄 분지의 가장자리에 걸쳐 있습니다. 일본의 가구야는 2007년 발사되어 이 분화구의 안쪽 벽을 찍고 바닥에서 뚜렷한 얼음은 보이지 않는다고 2008년 보고했습니다. 그 뒤 미국 루나 정찰 궤도선의 레이저 고도계는 바닥이 둘레보다 조금 밝다는 것을 재어, 얼음 서리가 흩어져 있을 가능성을 따졌습니다. 분화구 가장자리 근처의 능선은 아르테미스 III의 착륙 후보 지역에 듭니다."),
  apennines: t("아폴로 15호는 1971년 7월 30일 이 산맥의 기슭에 내렸고, 달에서 월면차를 처음 쓴 임무입니다. 월면차는 사흘 동안 약 27.9km를 달렸습니다. 우주비행사 스콧과 어윈은 흙과 돌 77kg을 모았고, 그중 40억 년이 넘은 흰 돌은 창세기 돌이라 불립니다. 근처의 해들리산은 약 4,600m 높이입니다. 스콧은 달에서 망치와 깃털을 같은 높이에서 놓아 둘이 함께 떨어지는 것을 보였고, 이 장면은 TV로 중계됐습니다. 두 사람이 밖에서 일한 시간은 세 번 합쳐 18시간 반쯤입니다."),
  alpineValley: t("알프스 산맥은 길이 약 280km이고 가장 높은 몽블랑은 약 3,600m입니다. 이름은 17세기 헤벨리우스가 지구의 알프스에서 따 붙였습니다. 골짜기는 산맥을 곧게 가로질러 비의 바다와 추위의 바다를 잇습니다. 골짜기 벽은 가파르고 바닥은 평평합니다. 근처에는 지름 57km의 카시니 분화구가 있고, 그 안에는 지름 약 15km의 작은 분화구 카시니 A가 들어 있습니다. 추위의 바다는 달 북쪽에 띠처럼 길게 이어진 바다로, 길이가 약 1,500km입니다. 바닥의 가는 홈은 용암이 흐른 자국으로 봅니다."),
  straightWall: t("구름의 바다는 지름 약 700km의 어두운 평원으로, 이름은 1651년 리치올리가 붙였습니다. 직선벽은 서쪽이 동쪽보다 내려앉은 단층으로, 용암이 채운 바다가 식고 무거워지며 가장자리 땅이 갈라진 것으로 봅니다. 바로 곁의 버트 분화구는 지름 17km이고, 그 곁에는 길이 약 50km의 버트 틈이 이어져 있습니다. 서쪽에는 지름 61km의 불리알두스 분화구가 가운데 봉우리를 품고 있습니다. 1964년 레인저 7호는 이 바다 곁의 알려진 바다에 부딪히기까지 사진 4,316장을 보냈습니다."),
  moscoviense: t("루나 3호는 1959년 10월 4일 발사되어 7일에 달 뒷면을 찍었습니다. 달 뒤쪽 약 6,200km 위를 지나며 29장을 찍었고, 그 가운데 알아볼 만한 17장을 지구로 보냈습니다. 소련 과학자들은 사진에 보이는 지형에 모스크바의 바다, 치올콥스키, 멘델레예프, 로모노소프 같은 이름을 먼저 붙였습니다. 달 뒷면의 약 70%가 이 사진으로 처음 드러났습니다. 이 카메라는 우주선 안에서 필름을 현상하고 말려 스캔한 뒤 전파로 보내는 방식이었습니다. 사진은 흐릿했지만 뒷면에는 바다가 거의 없고 산이 많다는 것을 처음 알려 주었습니다."),
  tsiolkovskiy: t("콘스탄틴 치올콥스키는 1857년 러시아에서 태어나 열 살 무렵 성홍열로 귀가 거의 들리지 않게 되었고, 학교에 다니지 못해 독학으로 공부했습니다. 1903년 로켓이 얻는 속도와 연료 양의 관계를 수식으로 정리한 논문을 냈습니다. 이 식은 지금도 로켓 설계의 기본에 쓰이며 치올콥스키 로켓 방정식이라 부릅니다. 1935년에 세상을 떠났으니 스푸트니크보다 22년 앞섭니다. 러시아 동쪽에는 그의 이름을 딴 도시 치올콥스키가 보스토치니 우주기지 곁에 있습니다."),
  serenitatis: t("루노호트 2호는 1973년 1월에 내려 약 4개월 동안 39km를 달렸고, 이 거리는 2014년 오퍼튜니티가 넘을 때까지 외계 천체 위 기록이었습니다. 아폴로 17호의 서난과 슈미트는 1972년 12월 11일 내려 사흘 동안 22시간 넘게 걸어 다니며 흙과 돌 약 110kg을 모았습니다. 슈미트는 지질학자로서 달에 간 유일한 우주비행사입니다. 이들은 지금까지 달에 마지막으로 선 사람입니다. 슈미트는 박사 학위가 있었습니다."),
  crisium: t("위난의 바다는 마스콘이라 부르는, 둘레보다 중력이 센 곳 가운데 하나입니다. 소련의 루나 20호는 1972년 2월 이 바다 북쪽 아폴로니우스 고지에 내려 약 55g의 흙을 가져왔습니다. 루나 24호가 가져온 현무암은 약 33억 년 전에 굳은 것입니다. 이름은 1651년 리치올리가 붙였고, 바다 서쪽에는 밝은 빛줄기를 뻗는 프로클루스 분화구가 있습니다. 루나 15호가 달을 도는 동안 소련은 아폴로 11호와 부딪히지 않도록 자신들의 궤도를 미국에 알렸습니다."),
  plato: t("플라톤의 이름은 고대 그리스 철학자에서 왔고, 1651년 리치올리가 붙였습니다. 남쪽에는 홀로 솟은 피코산과 피통산이 있고, 피코산은 높이 약 2,400m입니다. 또 길이 약 90km의 곧은 산줄기 몬테스 렉티가 있습니다. 옛 관측자들이 적은 바닥의 밝기 변화 가운데 일부는 햇빛이 비치는 각도가 달라지며 생긴 착시일 수 있습니다. 플라톤이 쓴 책에는 아틀란티스 이야기가 나옵니다. 분화구 서쪽 벽에는 크게 무너져 내린 자국이 있습니다."),
  aristarchus: t("1787년 윌리엄 허셜은 달의 어두운 쪽에서 이 분화구 근처가 붉게 빛나는 것을 보고 화산이라 생각했습니다. 1963년 미국 로웰 천문대의 두 관측자도 이곳에서 붉은 빛을 보았다고 보고했습니다. 분화구 깊이는 약 3.5km이고, 슈뢰터 계곡은 폭 10km쯤의 둥근 머리 부분에서 시작해 점점 좁아지는데, 그 모양 때문에 코브라 머리라는 별명이 붙었습니다. 기원전 3세기의 아리스타르코스는 해와 달까지의 거리를 비교하려 했고, 태양이 지구보다 훨씬 크다고 보았습니다."),
  keplerCrater: t("케플러가 1609년과 1619년에 발표한 행성 운동의 법칙은 행성이 타원 궤도를 돈다는 것을 담았습니다. 그는 죽은 뒤 1634년에 출간된 소설 꿈에서 달 여행을 그렸고, 이 책은 가장 오래된 SF의 하나로 꼽힙니다. 1604년 그가 관측한 신성은 케플러 초신성이라 불립니다. 2009년 NASA가 쏘아 올린 케플러 우주망원경은 그의 이름을 따서 지었으며 행성 2,600개 넘게를 확인했습니다. 그는 1571년에 태어나 1630년에 세상을 떠났습니다."),
  clavius: t("클라비우스 분화구 안에는 지름 약 50km의 작은 분화구 러더퍼드와 포터가 있어, 큰 분화구들의 활 모양 줄 가운데 가장 눈에 띕니다. 깊이는 약 3.5km입니다. 소피아는 보잉 747 비행기에 지름 2.7m 망원경을 실어 높이 12km 넘는 곳에서 관측했고, 2022년까지 운용됐습니다. 적외선으로 물 분자 특유의 신호를 잡아 이 분화구의 물을 알아냈습니다. 클라비우스는 독일 밤베르크에서 태어나 로마에서 가르쳤고, 그가 도운 그레고리력은 1582년부터 쓰였습니다."),
  iridum: t("무지개의 만이라는 이름은 1651년 이탈리아의 조반니 리촐리가 펴낸 달 지도에서 왔습니다. 만의 바닥에는 용암이 식으며 구겨진 주름 능선이 길게 남아 있습니다. 2013년 12월 14일 창어 3호는 이 만에서 가까운 비의 바다에 내려 위투 탐사차를 내려보냈습니다. 1976년 소련의 루나 24호 이후 37년 만에 달에 내린 탐사선이었고, 중국으로서는 첫 달 착륙이었습니다. 위투는 이듬해 1월 둘째 밤을 앞두고 이동 장치에 이상이 생겼지만 그 뒤로도 신호를 보냈습니다."),
  reinerGamma: t("이름은 가까이 있는 라이너 분화구에서 왔고, 감마는 옛 달 지도에서 그 둘레의 무늬를 가리키던 그리스 글자입니다. 이 자리의 자기장은 아폴로 15호와 16호가 남긴 작은 관측 위성과 1998년의 루나 프로스펙터가 궤도에서 쟀습니다. 지구 자기장보다는 훨씬 약하지만 둘레의 달 땅보다는 분명히 셉니다. 달 표면은 태양풍과 작은 운석에 맞아 해마다 어두워지는데, 이 무늬는 그 작용이 덜해서 밝게 남은 것으로 봅니다. 한편 자기장이 어떻게 생겼는지는 아직 정해지지 않았고, 옛 충돌의 흔적으로 보는 설도 있습니다."),
  olympus: t("꼭대기의 분화구는 용암이 차 있던 방이 비워질 때마다 무너져 생긴 여섯 개가 겹친 것으로, 가장 깊은 곳이 3km쯤 됩니다. 하와이의 마우나케아는 바다 밑바닥에서 재면 10km쯤인데, 올림푸스산은 그 두 배가 넘습니다. 유럽 마스 익스프레스의 사진을 분석한 연구에서는 비탈의 일부 용암이 수백만 년 전에 흘렀을 만큼 젊다고 보았습니다. 화성의 화산 활동이 완전히 끝나지 않았을 수 있다는 뜻입니다."),
  marineris: t("계곡은 하나의 홈이 아니라 멜라스, 코프라테스, 오피르 같은 이름을 가진 여러 골짜기가 이어진 무리입니다. 골짜기 벽에는 거대한 산사태 자국이 남아 있습니다. 궤도선들은 골짜기 안의 층진 퇴적물에서 물이 있어야 생기는 황산염 광물을 찾았습니다. 2021년 유럽의 ExoMars 가스 추적 궤도선은 계곡 한가운데 땅속에 물 성분이 많이 들어 있는 곳이 있음을 보였습니다. 사람이 간다면 물을 얻을 수 있는 후보지로 거론되는 이유입니다."),
  tharsis: t("타르시스 고원은 폭 5,000km쯤, 둘레 땅보다 10km쯤 높이 솟은 거대한 혹입니다. 이름은 성경에 나오는 먼 땅의 이름에서 따와 스키아파렐리가 붙였습니다. 화성에는 지각판이 움직이지 않아 이 아래의 뜨거운 곳이 수십억 년 동안 한자리에 머물며 용암을 쏟아 냈습니다. 그때 나온 이산화탄소와 수증기가 화성의 옛 대기와 기후에 영향을 주었다고 봅니다. 아르시아산 꼭대기의 분화구는 폭이 110km쯤 됩니다."),
  hellas: t("헬라스라는 이름은 1877년 스키아파렐리가 망원경으로 본 밝은 무늬에 그리스의 옛 이름을 붙인 데서 왔습니다. 분지는 화성의 먼지 폭풍이 자주 시작되는 곳으로 알려져 있고, 2001년 화성 전체를 덮은 큰 폭풍도 이곳에서 일어났습니다. 동쪽 가장자리에는 오래전 물이 흐른 듯한 골짜기가 이어지고, 비탈에는 빙하처럼 흘러내린 흙의 무늬가 있습니다. 분지 바닥은 둘레보다 크게 낮아 먼지와 얼음이 모이기 쉬운 곳입니다."),
  northCap: t("2008년 5월 25일 피닉스 착륙선이 북위 68도의 북극관 가까이에 내려 땅을 팠고, 흙 몇 cm 밑에서 물 얼음을 직접 확인했습니다. 피닉스는 하늘에서 눈이 내리는 것도 레이저로 보았고, 그해 11월 2일 겨울이 오며 전력이 끊겨 임무를 마쳤습니다. 화성 정찰 궤도선의 레이더는 얼음 속 2km 깊이까지 층을 비추어, 기후가 바뀔 때마다 얼음과 모래가 번갈아 쌓였음을 보였습니다. 북극관은 화성에서 가장 큰 물 얼음 창고입니다."),
  southCap: t("1969년 마리너 7호는 남극관 위를 지나며 적외선으로 온도를 재어, 이곳을 덮은 것이 얼어붙은 이산화탄소임을 알려 주었습니다. 두꺼운 드라이아이스 덮개는 극의 한가운데에서 조금 비켜 서 있습니다. 2018년 호수 같은 신호가 나온 곳 둘레에서 2020년 비슷한 신호가 몇 곳 더 나왔습니다. 그러나 이 깊이는 영하 수십 도라 소금이 아주 많이 녹아 있어야 물이 얼지 않고, 2021년 이후 연구들은 점토 같은 광물도 같은 신호를 낼 수 있다고 지적합니다."),
  korolev: t("이름의 주인 코롤료프는 살아 있는 동안 이름이 알려지지 않아 ‘수석 설계자’로만 불렸고, 1966년 세상을 떠난 뒤에야 이름이 공개되었습니다. 1938년 잘못된 죄목으로 체포되어 시베리아 수용소에서 지내기도 했습니다. 유럽의 마스 익스프레스는 이 분화구를 여러 궤도에서 찍은 사진을 이어 붙여 2018년 한 장으로 보여 주었습니다. 분화구 바닥 둘레에는 모래 언덕이 둘러 있고, 가운데 얼음 언덕이 분화구의 대부분 깊이를 채우고 있습니다."),
  cydonia: t("사진은 1976년 7월 25일에 찍혔고, 미국항공우주국은 당시 보도자료에서 빛과 그림자의 장난이라고 설명했습니다. 시도니아라는 이름은 그리스 크레타섬의 옛 도시 이름에서 왔고, 스키아파렐리가 망원경으로 본 밝은 지역에 붙였습니다. 1987년 한 저자가 책으로 이 얼굴을 외계 문명의 유적이라 주장하자 크게 퍼졌습니다. 1998년 4월 마스 글로벌 서베이어가 처음 다시 찍은 사진이 그 주장을 가라앉혔습니다."),
  syrtis: t("시르티스 메이저에는 니리 파테라와 메로에 파테라라는 화산 분화구가 있습니다. 궤도선은 니리 파테라 둘레에서 이산화규소가 많은 물질을 찾았는데, 뜨거운 물이 솟던 곳의 흔적일 수 있다고 봅니다. 20세기 초까지는 이 어두운 무늬의 계절 변화를 식물이 자라는 것으로 보는 사람도 있었습니다. 그 생각은 1960년대 탐사선들이 먼지가 바람에 움직이는 것임을 보이며 사라졌습니다. 동쪽 옆에는 지름 1,500km쯤의 이시디스 충돌 분지가 있습니다."),
  rosetta: t("혜성의 이름은 1969년 사진 건판에서 이 혜성을 찾아낸 소련의 천문학자 클림 추류모프와 스베틀라나 게라시멘코에서 왔습니다. 혜성은 두 덩어리가 붙은 고무 오리 모양이고, 가장 긴 쪽이 4km쯤입니다. 로제타의 장비는 혜성 물의 중수소 비율이 지구 바다의 세 배가 넘음을 재어, 지구의 물이 혜성에서 왔다는 생각에 의문을 던졌습니다. 또 혜성의 숨결에서 산소 분자가 나오는 것도 처음 확인했습니다."),
  pele: t("보이저 1호는 이오에서 활화산 아홉 곳을 찾았고, 넉 달 뒤 지나간 2호는 그 가운데 여덟 곳이 계속 뿜는 것을 보았습니다. 펠레만은 그 사이 분출을 멈춘 뒤였습니다. 뒷날 갈릴레오와 지상 망원경은 펠레 자리에 끓는 용암 호수가 있다고 보았습니다. 용암의 온도는 1,000도가 넘습니다. 분출이 멈춘 뒤에도 둘레의 붉은 고리는 1979년과 거의 같은 자리에 남아 있어, 이오의 땅이 얼마나 빨리 새로 덮이는지 보여 줍니다."),
  tigerStripes: t("2014년 카시니 사진을 분석한 연구는 줄무늬를 따라 약 100곳의 분출구를 찾았습니다. 분출은 초당 200kg 안팎의 물을 우주로 내보냅니다. 2015년 10월 카시니는 표면 위 49km까지 내려가 물기둥 속을 지났고, 2017년 발표에서 물기둥 속 수소 기체가 바닷속 바위와 뜨거운 물이 만나 생겼을 수 있다고 보았습니다. 2023년에는 얼음 알갱이에서 생명에 꼭 필요한 인이 든 염이 검출되었습니다."),
  shoemakerLevy: t("1993년 3월 24일 캘리포니아 팔로마산 천문대에서 찍은 사진에 진주 목걸이처럼 한 줄로 늘어선 혜성 조각들이 찍혀 있었습니다. 이름의 아홉이라는 숫자는 슈메이커 부부와 레비가 함께 찾은 아홉 번째 혜성이라는 뜻입니다. 조각에는 A부터 W까지 글자가 붙었습니다. 가장 큰 조각 G가 부딪힐 때의 힘은 TNT 600만 메가톤쯤으로 헤아립니다. 목성이 열 시간쯤에 한 바퀴 돌아 충돌 자리가 지구 쪽으로 돌아오자 허블 우주망원경이 그 자국을 찍었습니다."),
  venera13: t("착륙선은 지구로 곧바로 신호를 보내지 못해, 위를 나는 비행체가 받아 지구로 중계했습니다. 카메라는 빨강, 초록, 파랑 필터를 차례로 써서 색을 얻었고, 사진 속 금성의 하늘과 땅은 주황빛이었습니다. 흙을 분석해 보니 칼륨이 많은 현무암이어서, 지구의 특정 화산암과 비슷한 성분이었습니다. 바람은 초속 1m 안팎의 느린 바람이었습니다. 쌍둥이 베네라 14호는 57분을 버텼습니다."),
  tombaughRegio: t("명왕성은 1930년 2월 18일 로웰 천문대의 사진 건판 비교로 확인되었고, 이름은 영국 옥스퍼드의 열한 살 소녀 베네티아 버니가 지어 보냈습니다. 뉴허라이즌스는 2006년 1월 19일 떠나 2015년 7월 14일 명왕성 위 12,500km를 지났습니다. 이 탐사선에는 2.5년 앞서 세상을 뜬 톰보의 유해 일부가 실려 있습니다. 하트 모양은 위치가 일정해서, 명왕성은 하트가 늘 카론 쪽을 향한 채 돕니다."),
  hexagon: t("육각형을 처음 알아본 사람은 미국의 데이비드 고드프리로, 보이저 자료를 다시 살피다 찾았습니다. 한 바퀴 도는 데 10시간 39분 24초가 걸리는데, 이것은 보이저 때 라디오 신호로 쟀던 토성 속 자전 주기와 같습니다. 육각형의 폭은 가로질러 3만km쯤으로 지구 지름의 두 배를 넘습니다. 카시니는 2013년 육각형 한가운데 태풍의 눈을 아주 가까이서 찍었습니다. 눈의 둘레에서는 구름이 시속 500km 안팎으로 돕니다."),
  naro: t("누리호의 첫 발사는 2021년 10월 21일이었고, 3단 엔진이 계획보다 일찍 꺼져 위성 모형을 궤도 속도까지 올리지 못했습니다. 원인을 고친 2022년 6월 두 번째 발사가 성공했고, 2023년 5월 25일 세 번째 발사에서는 실제로 쓰는 차세대소형위성 2호 등을 궤도에 올렸습니다. 발사장은 남쪽 바다를 향해 있어 로켓이 사람이 사는 곳 위를 날지 않습니다. 센터는 한국항공우주연구원이 운영합니다."),
  messenger: t("메신저라는 이름은 수성의 표면, 우주 환경, 지구화학, 거리 측정을 뜻하는 영어 낱말의 머리글자를 모은 것입니다. 2004년 8월 3일 떠난 탐사선은 2008년과 2009년에 수성을 세 번 스친 뒤 궤도에 들었습니다. 수성의 자기장 중심이 행성 중심에서 북쪽으로 반지름의 5분의 1쯤 치우쳐 있음을 밝혔고, 2012년에는 극지 분화구의 물 얼음을 확인했습니다. 수성 땅에 황과 칼륨 같은 휘발성 원소가 예상보다 많다는 것도 알아냈습니다."),
  conamara: t("혼돈 지형은 유로파 곳곳에 있고, 얼음 껍질이 얇아지거나 아래의 물이 올라와 생겼다고 봅니다. 갈릴레오는 1989년 우주왕복선에서 떠나 2003년 9월 21일 목성 대기에 일부러 뛰어들었습니다. 훗날 유로파에 지구의 미생물이 옮겨 가는 일을 막기 위해서였습니다. 후속 탐사선 유로파 클리퍼는 2024년 10월 14일 떠났고, 2030년 도착해 유로파 곁을 49번 스칠 계획입니다."),
  venera7: t("7호는 1970년 8월 17일 떠나 넉 달 가까이 날았습니다. 신호가 약했던 것은 착륙선이 넘어져 안테나가 지구에서 벗어났기 때문으로 봅니다. 뒤를 이은 베네라 8호는 1972년 7월 22일 금성의 낮 쪽에 내려 50분쯤 신호를 보냈고, 땅의 흙 성분을 처음 쟀습니다. 그 뒤 1975년의 베네라 9호는 금성 표면의 첫 사진을 보냈습니다. 7호의 성공이 이 길을 열었습니다."),
  occator: t("던은 2007년 9월 27일 떠나 2011년 소행성 베스타를 먼저 돌았고, 2015년 3월 6일 세레스에 닿았습니다. 두 천체를 차례로 돈 탐사선은 던이 처음입니다. 세레스는 1801년 1월 1일 이탈리아의 주세페 피아치가 찾았고, 지름이 940km로 소행성대에서 가장 큽니다. 던은 연료가 다해 2018년 11월 1일 임무를 마쳤고, 지금도 세레스 둘레를 돌고 있습니다. 앞으로 수십 년은 세레스에 떨어지지 않을 것으로 봅니다."),
  lc39a: t("39A에서 처음 뜬 새턴 5는 1967년 11월 9일의 무인 아폴로 4호였고, 1973년 5월에는 우주정거장 스카이랩을 올렸습니다. 우주왕복선 컬럼비아호의 첫 비행은 1981년 4월 12일, 마지막 비행 애틀랜티스호는 2011년 7월 8일 이곳에서 떠났습니다. 스페이스X의 팰컨 헤비는 2018년 2월 6일 첫 비행을 이곳에서 했습니다. 2020년 5월 30일 크루 드래건을 탄 우주인은 더그 헐리와 밥 벤켄입니다."),
  kraken: t("2009년 7월 카시니의 적외선 카메라는 타이탄 북극의 호수 면이 햇빛을 거울처럼 되받는 것을 처음 보았습니다. 호수에 액체가 있다는 가장 확실한 증거였습니다. 타이탄의 한 해는 지구 해로 29.5년이라 계절 하나가 7년쯤 갑니다. 2005년 호이겐스는 적도 가까이의 마른 땅에 내려 말라붙은 강바닥을 찍었습니다. 미국의 드래건플라이 헬리콥터는 2028년 발사해 2034년 도착할 계획입니다."),
  mordor: t("카론은 1978년 6월 미국 해군 천문대의 제임스 크리스티가 명왕성 사진이 한쪽으로 길쭉하게 번진 것을 보고 찾았습니다. 그는 아내 샬린의 이름과 닮았다는 이유로 카론이라는 이름을 밀었습니다. 카론의 지름은 1,212km로 명왕성의 절반이 넘고, 두 천체는 서로 한쪽 면만 보인 채 19,600km 떨어져 돕니다. 둘의 무게 중심은 명왕성 바깥에 있어, 명왕성과 카론은 서로 둘레를 도는 한 쌍에 가깝습니다."),
  greatDarkSpot: t("해왕성은 태양빛을 지구의 900분의 1쯤밖에 받지 못하지만, 받는 열의 2.6배를 내보냅니다. 속에서 나오는 이 열이 폭풍과 빠른 바람을 먹여 살린다고 봅니다. 대기는 수소와 헬륨이 대부분이고, 메탄이 붉은 빛을 흡수해 푸른빛을 만듭니다. 해왕성은 1846년에 발견되었고, 한 해가 지구의 약 165년이라 2011년에야 발견된 자리로 처음 돌아왔습니다."),
  voyager2Neptune: t("트리톤 표면 온도는 영하 235도로, 태양계에서 잰 땅 가운데 가장 차가운 축에 듭니다. 트리톤은 해왕성의 자전과 반대 방향으로 돌아서, 먼 곳에서 붙잡혀 온 천체로 봅니다. 해왕성의 자기장 축은 자전축에서 47도 기울어 있어 천왕성과 비슷하게 크게 어긋납니다. 보이저 2호는 1977년 8월 20일 쌍둥이 1호보다 16일 먼저 떠났고, 행성들이 한 방향에 늘어서는 175년에 한 번의 기회를 써서 네 행성을 차례로 지났습니다."),
  voyager2Uranus: t("천왕성의 자전축은 98도 누워 있어, 1986년에는 남극이 태양을 마주 보고 있었습니다. 보이저 2호는 라디오 신호의 변화로 하루의 길이가 17시간 14분임을 처음 재었고, 새로 찾은 위성 가운데 가장 큰 퍽은 지름이 162km쯤입니다. 2022년 미국의 행성과학 10년 계획은 천왕성 궤도선과 대기 탐사선을 다음 큰 임무 가운데 가장 앞에 올렸습니다. 천왕성에는 40년 가까이 새 탐사선이 가지 못했습니다."),
  yiSoyeon: t("소유스 TMA-12의 승무원은 러시아의 세르게이 볼코프, 올레그 코노넨코와 이소연이었습니다. 이소연은 1978년 광주에서 태어나 한국과학기술원에서 공부한 생명공학자이고, 비행은 모두 10일 21시간쯤이었습니다. 볼코프와 코노넨코는 정거장에 남았고, 이소연은 돌아오는 소유스 TMA-11에 미국의 페기 휘트슨, 러시아의 유리 말렌첸코와 함께 탔습니다. 그 귀환선이 가파르게 떨어졌습니다."),
  voyager2Out: t("보이저 2호는 1977년 8월 20일 쌍둥이 1호보다 16일 먼저 떠났고, 둘 다 지구의 소리와 그림을 담은 금빛 음반을 싣고 있습니다. 2호가 넘은 경계에서는 플라스마의 밀도가 갑자기 높아졌습니다. 원자력 전지의 전력이 해마다 4와트쯤 줄어, 장치를 하나씩 끄며 2030년대까지 신호를 이어 가려 합니다. 신호가 지구에 닿는 데 17시간쯤 걸립니다. 2020년에는 캔버라 안테나를 고치는 여덟 달 동안 명령을 보내지 못했습니다."),
  parkerPerihelion: t("탐사선의 이름은 1958년 태양에서 입자가 끊임없이 불어 나온다는 태양풍 이론을 내놓은 유진 파커에서 땄습니다. 살아 있는 사람의 이름을 딴 NASA의 첫 탐사선이고, 2018년 8월 발사 때 91세의 파커가 현장에서 지켜보았습니다. 탐사선은 태양풍 속에서 자기장의 방향이 순간 꺾이는 스위치백이라는 현상을 찾았습니다. 2021년 4월에는 코로나 안으로 들어갔고, 그 사실은 같은 해 12월에 발표되었습니다."),
  acidalia: t("이름은 그리스 신화에서 아프로디테가 목욕했다는 샘에서 왔고, 1877년 스키아파렐리가 붙였습니다. 평원은 북위 47도 둘레에 걸쳐 폭이 3,000km 가까이 됩니다. 화성의 북반구에서 봄과 가을에 일어나는 먼지 폭풍은 이 평원 위로 남쪽을 향해 내려가는 길을 자주 지납니다. 그래서 아키달리아는 화성 날씨를 살필 때 주목하는 길목 가운데 하나입니다. 탐사선이 내린 적은 없지만 궤도선은 이곳을 오래 살폈습니다."),
  schiaparelli: t("스키아파렐리는 밀라노 브레라 천문대에서 일했고, 1877년 화성이 가장 가까워진 때 밝은 곳과 어두운 곳을 잇는 가는 줄무늬 지도를 그렸습니다. 화성에 지금도 쓰는 지명 수십 개를 정한 사람입니다. 수성이 늘 같은 면을 태양에 향한다고 보았으나 1965년 레이더로 틀렸음이 밝혀졌습니다. 2016년 10월 19일 시험 착륙선은 관성 측정 장치가 잠깐 오작동해 약 3.7km 높이에서 낙하산을 일찍 버리고 땅에 부딪혔습니다."),
  wadiRum: t("와디럼의 가장 높은 봉우리 움 앗 다미산은 요르단 전체에서 가장 높은 곳으로, 1,850m쯤입니다. 바위 사이에는 1세기에 나바테아 사람들이 세운 신전의 터가 남아 있습니다. 1917년 아랍 반란 때 영국 장교 로런스가 이곳을 지나 아카바로 갔고, 그 이야기가 훗날 영화가 되었습니다. 2000년 영화 「레드 플래닛」을 비롯해 2015년 「마션」, 2021년 「듄」이 이 사막에서 촬영되었습니다. 지금도 유목민 베두인이 이곳에 삽니다."),
  baikonur: t("1957년 5월 15일 R-7 로켓의 첫 시험은 실패였고, 8월 21일의 시험이 성공해 같은 로켓으로 스푸트니크를 올렸습니다. 1957년 11월 3일에는 개 라이카를 태운 스푸트니크 2호가 떠났습니다. 1960년 10월 24일에는 로켓이 발사대에서 폭발해 수십 명이 숨졌습니다. 소련의 우주왕복선 부란은 1988년 11월 15일 이곳에서 사람 없이 단 한 번 날았습니다. 발사장의 넓이는 6,700km²가 넘습니다."),
  chicxulub: t("2016년 국제 시추단이 바다 밑 지층 1,300m 가까이 구멍을 뚫어, 충돌 때 솟아오른 화강암 고리를 시료로 직접 확인했습니다. 충돌의 힘은 히로시마 원자폭탄의 10억 배가 넘는 것으로 헤아립니다. 충돌로 솟은 먼지와 황 입자가 햇빛을 가려 여러 해 동안 기온이 떨어졌습니다. 시추 시료에는 충돌 뒤 얼마 지나지 않아 이 자리에 생물이 돌아온 흔적도 들어 있었습니다."),
  barringer: t("충돌 속도는 초속 12km쯤이었고, 폭발의 세기는 TNT 1,000만 톤쯤으로 헤아립니다. 구덩이의 테두리는 둘레 평원보다 45m쯤 솟아 있습니다. 땅 곳곳에서 수집한 캐니언 디아블로 운석 조각은 지금까지 수십 톤이 모였습니다. 배린저는 1906년 광산 회사를 세워 땅속의 철을 찾으려 했고, 그가 세상을 떠난 1929년에도 찾지 못했습니다. 지금 학계의 공식 이름은 배린저 충돌구이고, 사람들은 흔히 운석공이라 부릅니다."),
  maunaKea: t("켁 망원경의 거울은 통짜가 아니라 지름 1.8m인 육각형 거울 36장을 맞붙여 만듭니다. 컴퓨터가 각 조각의 위치를 1초에 두 번씩 나노미터 단위로 바로잡습니다. 켁 1호는 1993년, 2호는 1996년에 첫 빛을 받았습니다. 스바루 망원경은 1999년부터 지름 8.2m 거울로 넓은 하늘을 한꺼번에 찍어 왔습니다. 2020년 노벨 물리학상을 받은 안드레아 게즈는 켁 망원경으로 우리 은하 한가운데 별들의 움직임을 재어 거대한 블랙홀이 있음을 확인했습니다. 켁 망원경 두 대는 따로 쓰지 않고 함께 모아 하나의 간섭계로도 쓸 수 있습니다. 두 거울 사이의 거리가 더 큰 망원경의 눈이 됩니다."),
  alma: t("알마는 1mm 안팎의 짧은 전파를 봅니다. 이 전파는 차갑고 빛이 가려진 먼지와 가스를 잘 비춥니다. 2014년 어린 별 HL 타우를 찍은 사진에서는 먼지 원반에 여러 겹의 둥근 틈이 보였고, 갓 생겨나는 행성이 길을 쓸어 낸 자국으로 봅니다. 사람이 머무는 기지는 해발 2,900m에 따로 두어, 안테나가 있는 5,000m에는 꼭 필요한 시간만 올라갑니다. 차이난토르는 이 지방의 옛 말로 출발하는 곳이라는 뜻으로 알려져 있습니다. ALMA는 스페인어로 영혼을 뜻하는 낱말과 같습니다. 영문 이름은 아타카마 대형 밀리미터·서브밀리미터 배열의 머리글자입니다."),
  bohyunsan: t("한국천문연구원은 칠레, 남아프리카공화국, 호주에 지름 1.6m 망원경을 한 대씩 두고 2015년부터 KMTNet이라는 관측망을 운영합니다. 세 곳이 지구를 돌며 차례로 이어받아 같은 하늘을 거의 쉬지 않고 지켜봅니다. 먼 별빛이 사이를 지나는 다른 별의 중력에 휘어 잠깐 밝아지는 현상을 잡아 외계 행성을 찾는 것이 주된 일입니다. 한국은 2012년 지름 8.4m 거울 일곱 장으로 이루어질 거대마젤란망원경 사업에도 참여했습니다. 각 망원경의 카메라는 한 번에 4제곱도의 하늘을 담아, 별이 많은 은하 중심 쪽을 넓게 훑습니다."),
  tanegashima: t("이곳에서는 일본의 우주 화물선과 소행성 탐사선도 떠났습니다. 고노토리라고 부른 보급선 HTV는 2009년 9월부터 2020년 5월까지 H-IIB 로켓에 실려 아홉 번 국제우주정거장에 짐을 날랐습니다. 2014년 12월 3일에는 H-IIA가 소행성 탐사선 하야부사2호를 올렸습니다. 하야부사2호는 소행성 류구에서 모은 돌가루 약 5.4g이 든 캡슐을 2020년 12월 6일 호주 사막에 떨어뜨렸습니다. 발사장은 일본 우주항공연구개발기구 JAXA가 운영합니다. 2024년 2월 17일에는 새 주력 로켓 H3의 2호기가 이곳에서 성공했습니다. 앞서 2023년 3월의 1호기는 2단 엔진이 켜지지 않아 실패했습니다."),
  wenchang: t("2024년 5월 3일에는 창정 5호가 창어 6호를 싣고 이곳에서 떠났습니다. 창어 6호는 6월 초 달 뒷면의 아폴로 분지에 내려 흙을 퍼 담았고, 6월 25일 내몽골 사막에 돌아왔습니다. 달 뒷면의 흙을 가져온 것은 사람이 처음입니다. 흙의 무게는 1,935.3g이었습니다. 원창은 위도가 약 19도로 중국의 발사장 가운데 적도에 가장 가깝습니다. 2016년 11월 3일 창정 5호의 첫 발사도 이곳에서 있었습니다. 2021년 4월 29일에는 창정 5B호가 톈궁 정거장의 중심 모듈 톈허를 올렸고, 톈허의 무게는 22톤쯤입니다."),
  caloris: t("메신저의 사진은 분지 바닥이 용암이 굳은 매끈한 평원임을 보여 줍니다. 바닥에는 둥근 주름 능선과 갈라진 틈이 겹쳐 있어, 용암이 식어 줄고 가라앉으며 땅이 뒤틀린 것으로 봅니다. 매리너 10호는 1974년 3월부터 1975년 3월까지 세 번 수성 곁을 지나 겉의 45%쯤을 찍었습니다. 메신저는 2011년 3월부터 4년 남짓 수성을 돌았고, 2013년 3월 수성 전체의 지도를 완성했습니다. 칼로리스 분지의 정반대편에 기묘한 지형이 있다는 것도 이 충돌이 얼마나 컸는지 보여 주는 근거로 꼽힙니다. 이름은 매리너 10호 연구팀이 지었습니다."),
  prokofiev: t("메신저가 2012년 11월 발표한 값에 따르면 북극 분화구들에 갇힌 물 얼음은 1,000억 → 1조 톤으로 어림됩니다. 이만한 얼음이면 미국 워싱턴 D.C. 전체를 두께 3 → 5km의 얼음 덩어리로 감쌀 수 있습니다. 얼음 위를 덮은 어두운 물질은 두께가 10 → 20cm쯤으로, 햇빛에 얼음이 녹지 않게 담요처럼 지켜 주는 것으로 봅니다. 메신저는 2015년 4월 30일 연료가 떨어지자 수성 표면에 부딪히며 임무를 마쳤습니다. 메신저는 2011년 3월 18일 수성 궤도에 들어간 첫 탐사선이 되었습니다. 처음 계획한 1년을 넘겨 4년 넘게 임무를 이어 갔습니다."),
  discoveryRupes: t("디스커버리호는 1776년 영국을 떠난 제임스 쿡의 세 번째 항해에서 레졸루션호와 짝을 이룬 배입니다. 쿡이 1779년 2월 하와이에서 목숨을 잃자 디스커버리호의 선장 찰스 클러크가 탐험을 이어받았지만, 그도 같은 해 8월 병으로 세상을 떠났습니다. 두 배는 1780년 10월 영국으로 돌아왔습니다. 수성의 절벽은 달과 달리 행성 전체에 걸쳐 있어서, 매리너 10호의 사진 이래 수성이 식으며 쭈그러들었다는 증거로 꼽힙니다. 클러크는 러시아 캄차카의 페트로파블롭스크 앞바다에서 숨졌고 그곳에 묻혔습니다."),
  weirdTerrain: t("이 땅을 처음 찍은 매리너 10호는 1973년 11월 3일 지구를 떠나 1974년 2월 금성에서 중력의 도움을 받아 방향을 틀었고, 3월 29일 수성에 닿았습니다. 금성의 중력으로 다른 행성에 간 첫 탐사선이며, 한 탐사선이 행성 둘을 찾아간 것도 처음입니다. 1975년 3월 방향을 잡는 데 쓰는 질소 가스가 떨어져 교신이 끊겼고, 지금도 태양 둘레를 돌고 있습니다. 매리너 10호는 수성과 금성 사진을 합쳐 7,000장 넘게 지구로 보냈습니다. 사진 속 수성은 달과 닮았지만 평원과 절벽이 달과 다르게 퍼져 있었습니다."),
  hollows: t("할로는 깊이가 수십 m이고 바닥이 푸르스름하게 보이는 점이 특징입니다. 2011년 9월 메신저 연구팀이 과학 학술지에 처음 알렸습니다. 황 같은 날아가기 쉬운 성분이 많은 땅에서 생긴 것으로 보는 연구가 많고, 지금도 자라고 있을 수 있다고 합니다. 유럽과 일본이 함께 보낸 베피콜롬보는 2018년 10월 20일 떠나 2026년 말 수성 궤도에 들어갈 예정이며, 할로를 더 가까이에서 살필 것입니다. 할로라는 이름은 속이 빈 곳을 뜻하는 영어 낱말에서 왔고, 메신저 연구팀이 이 지형을 가리키려고 새로 쓴 이름입니다."),
  hokusai: t("호쿠사이는 1760년 에도에서 태어나 1849년까지 산 일본의 화가입니다. 호쿠사이라는 이름은 1798년부터 썼고, 평생 이름을 서른 번 가까이 바꾸었습니다. 큰 파도 그림 가나가와 해변의 높은 파도 아래는 1831년쯤 나온 후가쿠 36경이라는 연작 가운데 한 장입니다. 19세기 말 유럽에서 일본 판화가 인기를 끌 때 이 그림은 서양 화가들이 즐겨 모으는 작품이 되었습니다. 호쿠사이 분화구의 빛줄기는 수성에서 가장 길게 뻗은 것 가운데 하나로 꼽힙니다. 후가쿠 36경은 이름과 달리 실제로는 46장으로 이루어져 있습니다."),
  vivaldi: t("안토니오 비발디는 1678년 베네치아에서 태어났습니다. 머리털이 붉어 붉은 머리 사제라고 불렸고, 1703년 사제가 되었습니다. 같은 해부터 고아 소녀들을 돌보는 피에타 시설에서 바이올린을 가르쳤습니다. 사계가 들어 있는 협주곡집은 1725년 암스테르담에서 펴냈습니다. 비발디는 1741년 빈에서 세상을 떠났고, 그의 곡은 오랫동안 잊혔다가 20세기에 다시 연주되기 시작했습니다. 사계의 네 곡에는 계절의 풍경을 묘사한 짧은 시가 붙어 있어, 곡의 어느 대목이 무엇을 그린 것인지 알 수 있습니다."),
  vega: t("1986년 3월 6일 베가 1호가 8,890km, 9일 베가 2호가 8,030km 거리에서 핼리 혜성의 핵 곁을 지났습니다. 두 탐사선은 핵이 길이 15km쯤의 감자 같은 모양이고 표면이 매우 어둡다는 것을 알렸습니다. 이때 정확히 잰 핵의 위치는 유럽우주국의 조토가 3월 14일 596km까지 다가가는 길잡이가 되었습니다. 베가 착륙선들도 금성 땅에 내려 흙의 성분을 쟀습니다. 베가 1호와 2호는 1984년 12월 15일과 21일에 카자흐스탄의 바이코누르에서 프로톤 로켓으로 떠났습니다."),
  venera9: t("베네라 9호보다 앞서 베네라 7호가 1970년 12월 15일 금성에 내려, 다른 행성의 땅에서 처음 신호를 보냈습니다. 신호는 23분쯤 이어졌습니다. 베네라 9호는 감마선 측정기로 바위가 현무암과 비슷한 성분임을 알아냈고, 땅 가까이 부는 바람은 초속 1m도 안 되는 약한 바람임을 쟀습니다. 1982년 3월 베네라 13호와 14호는 금성 땅의 색깔이 담긴 사진을 처음 보냈습니다. 베네라 9호는 1975년 6월 8일, 10호는 6월 14일에 프로톤 로켓으로 떠났고, 금성까지 넉 달 반쯤 걸렸습니다."),
  galileoProbe: t("탐사구가 잰 공기에서 헬륨은 태양을 이룬 처음 가스보다 조금 적었습니다. 탄소, 황, 아르곤 같은 무거운 원소는 태양보다 2에서 3배 많았습니다. 목성이 이런 원소를 품은 얼음 덩어리를 먼저 모은 뒤 가스를 끌어당겼다는 생각을 뒷받침하지만, 아직 논란이 있습니다. 갈릴레오 탐사선 본체는 1989년 10월 18일 우주왕복선 애틀랜티스에 실려 떠났고, 2003년 9월 21일 유로파에 지구 생물이 옮겨 가지 않도록 일부러 목성의 공기 속으로 들어가 임무를 마쳤습니다."),
  valhalla: t("칼리스토는 목성에서 약 188만km 떨어져 있어, 갈릴레이 위성 가운데 목성의 강한 방사선을 가장 덜 받습니다. 그래서 NASA는 2003년의 연구에서 목성계 탐사에서 사람이 머무를 기지 후보로 칼리스토를 꼽았습니다. 갈릴레오 탐사선이 잰 자기장의 변화로 보아 얼음 겉 아래에 소금물 바다가 있을 수 있다는 의견도 있습니다. 칼리스토는 16.7일에 한 바퀴 돌며 늘 같은 면을 목성에 향합니다. 칼리스토는 지름이 4,821km로 수성과 거의 맞먹지만 질량은 훨씬 작습니다. 갈릴레이가 1610년 처음 본 네 위성 가운데 가장 바깥에 있습니다."),
  galileoRegio: t("갈릴레이는 1610년 1월 7일 밤 목성 곁에서 작은 별 셋을 보았고 며칠 뒤 넷으로 세었습니다. 이 네 위성의 이름은 독일의 시몬 마리우스가 1614년 책에서 붙인 것입니다. 가니메데는 그리스 신화에서 제우스가 독수리로 변해 데려간 미소년의 이름입니다. 가니메데는 7.15일에 한 바퀴 돌며, 이오, 유로파와 궤도가 1 대 2 대 4로 맞물려 서로를 당깁니다. 보이저 2호는 1979년 7월 9일 가니메데에 약 62,000km까지 다가가 어두운 땅과 밝은 고랑 지형의 경계를 처음 자세히 보여 주었습니다."),
  greatRedSpot: t("대적점의 바람은 가운데에서는 거의 없다가 가장자리로 갈수록 빨라지며, 한 바퀴 도는 데 지구 날로 6일쯤 걸립니다. 구름 꼭대기는 둘레보다 8km쯤 높이 솟아 있습니다. 2019년 허블 우주망원경은 대적점에서 붉은 조각들이 떨어져 나가는 모습을 찍었지만, NASA는 폭풍이 무너지는 것은 아니라고 설명했습니다. 1979년 3월에는 보이저 1호가 대적점을 가까이 찍어, 폭풍 속의 구름이 소용돌이치는 모습을 처음 보여 주었습니다. 이 점은 작은 망원경으로도 알아볼 수 있어, 아마추어 관측자들도 오래 지켜봐 왔습니다."),
  osiris: t("가니메데는 지름이 수성보다 8%쯤 크지만 돌 대신 얼음이 많아 질량은 수성의 절반이 안 됩니다. 유럽우주국의 주스는 2023년 4월 14일 떠나 2031년 7월 목성에 닿고, 2034년 12월 가니메데 둘레 궤도에 들어갑니다. 지구의 달이 아닌 위성을 도는 첫 탐사선이 됩니다. 가니메데 위를 지나는 길에는 얼음 밑 바다의 깊이와 얼음 껍질의 두께를 레이더로 재는 일도 맡습니다. NASA의 유로파 클리퍼도 2024년 10월에 떠나 2030년 목성에 닿을 예정이어서, 목성의 얼음 위성들을 두 탐사선이 함께 살피게 됩니다."),
  inktomi: t("레아는 지름 1,527km로 토성의 위성 가운데 둘째로 큽니다. 1672년 12월 23일 지오반니 카시니가 찾았고, 탐사선 카시니는 그의 이름을 딴 것입니다. 밀도가 물의 1.24배쯤이어서 얼음이 4분의 3쯤이고 나머지는 돌입니다. 레아는 토성을 4.5일에 한 바퀴 돌며 늘 같은 면을 토성에 향합니다. 이름은 그리스 신화에서 크로노스의 아내이자 제우스의 어머니인 여신 레아에게서 왔습니다. 카시니는 2004년 7월 토성 궤도에 들어가 13년 가까이 토성계를 살폈고, 2017년 9월 15일 토성의 공기 속으로 뛰어들어 임무를 마쳤습니다."),
  whiteSpot: t("1876년 12월 미국의 아사프 홀이 첫 하얀 폭풍을 기록했고, 이듬해 그는 화성의 두 위성 포보스와 데이모스를 찾았습니다. 1933년의 폭풍은 영국의 아마추어 천문가이자 코미디 배우였던 윌 헤이가 8월 3일 찾았습니다. 1990년의 폭풍은 미국의 아마추어 스튜어트 윌버가 먼저 보았습니다. 토성은 약 10시간 33분에 한 바퀴 자전하고 태양을 도는 데 29.4년이 걸려서, 이 폭풍은 한 번 오면 한 세대에 한 번 볼 수 있는 일입니다. 탐사선이 큰 하얀 폭풍을 가까이서 지켜본 것은 카시니가 처음입니다."),
  herschel: t("미마스는 토성에서 약 18만 5,500km 떨어져 22.6시간에 한 바퀴 돕니다. 밀도가 물의 1.15배쯤이어서 거의 얼음덩어리입니다. 미마스의 중력은 토성 고리 사이에 비어 있는 카시니 틈을 만드는 데 한몫합니다. 틈 가장자리의 알갱이는 미마스가 한 바퀴 돌 때 토성을 두 바퀴 돌아서, 늘 같은 자리에서 미마스에게 당겨져 밀려납니다. 허셜은 구경 1.2m의 40피트 망원경으로 미마스를 찾았습니다. 카시니는 2010년 2월 13일 미마스에 약 9,500km까지 다가가 허셜 분화구를 가까이 찍었습니다."),
  rubin: t("카메라 앞쪽 렌즈는 지름 1.55m로, 천문용으로 만든 렌즈 가운데 가장 큽니다. 한 장에 보름달 40개가 넘는 넓이의 하늘이 담깁니다. 30초 노출을 밤새 되풀이해 하룻밤에 1,000장 가까이 찍고, 10년 동안 은하 약 200억 개와 별 약 170억 개를 기록할 계획입니다. 같은 곳을 되풀이해 찍으니, 밝기가 변하는 별이나 갑자기 터지는 초신성이 있으면 몇 분 안에 알림이 나갑니다. 첫 사진은 처녀자리 은하단의 한쪽을 담았고, 삼렬성운과 석호성운의 사진도 함께 나왔습니다."),
  meerkat: t("미어캣의 접시 64대는 SKA의 중부 전파망원경 안으로 들어갑니다. 이 망원경은 접시 197대로 이루어지는데, 새로 짓는 133대에 미어캣의 64대를 더한 숫자입니다. 오스트레일리아에는 SKA 저주파가 막대 모양 안테나 13만 대 넘게로 지어집니다. 미어캣은 2016년 접시 16대만으로 첫 사진을 내놓았고, 2018년 64대가 모두 갖춰져 문을 열었습니다. 2007년 남아프리카공화국은 천문 지역 보호법을 만들어, 카루 일대에서 전파를 내는 기기를 법으로 막고 있습니다."),
  salt: t("SALT의 거울은 기울기가 고정되어 있어, 하늘의 한 고리 모양 띠 안에 있는 천체만 볼 수 있습니다. 한 천체를 한 번에 따라가는 시간은 1시간에서 2시간 반쯤입니다. 대신 구조가 단순해서 같은 크기의 일반 망원경보다 훨씬 싸게 지을 수 있었습니다. 실제로 빛을 모으는 면적은 지름 9m쯤의 거울과 맞먹습니다. 별빛을 무지개로 나누어 성분과 속도를 재는 분광 관측이 주된 일입니다. SALT는 남아프리카 천문대(SAAO)가 운영하고, 본부는 케이프타운에 있습니다. 서덜랜드의 같은 기지에는 지름 1.9m 망원경도 있습니다."),
  fast: t("FAST는 접시를 통째로 움직이지 않고, 바닥 판 4,450장을 아래에서 잡아당기는 장치 2,200개쯤으로 그때그때 지름 300m 부분을 포물면으로 만듭니다. 수신기를 실은 캐빈은 둘레 탑 여섯 개에서 내려온 케이블 여섯 가닥에 매달려 접시 위 140m쯤에서 움직입니다. 난런둥 박사가 1994년 이 계획을 처음 내놓았고, 공사는 2011년에 시작해 2016년에 끝났습니다. 난런둥은 완공 이듬해인 2017년에 세상을 떠났습니다. 2023년 6월에는 중국 연구팀이 FAST로 펄서들의 신호를 모아 우주를 울리는 중력파 배경의 증거를 찾았다고 발표했습니다."),
  jantarMantar: t("자이 싱은 작은 놋쇠 기구는 눈금이 거칠어 오차가 크다고 보고, 기구를 돌로 크게 지으면 오차가 줄어든다고 믿었습니다. 천문대는 1724년 델리에 먼저 지었고, 1727년 자이푸르 도시를 세운 뒤 자이푸르의 것을 지었습니다. 자이푸르에는 황도 열두 별자리마다 하나씩 맞춘 기구 열두 개가 있습니다. 그는 유럽의 천문 표도 들여와 살폈지만, 자신이 직접 재서 고친 표를 만들어 1735년 무렵 펴냈습니다. 이곳의 기구 가운데는 해시계뿐 아니라 별과 해의 높이를 재는 것도 있어서, 하나하나가 다른 쓰임새를 가졌습니다."),
  lowell: t("톰보는 당시 스물네 살이었고, 캔자스의 농장에서 직접 만든 망원경으로 그린 목성과 화성 스케치를 로웰 천문대에 보낸 일이 인연이 되어 1929년 이곳에 들어왔습니다. 발견은 1930년 3월 13일에 발표되었는데, 이날은 퍼시벌 로웰이 태어난 날이었습니다. 톰보의 유해 일부는 2006년 1월 떠난 뉴호라이즌스호에 실려, 2015년 7월 14일 명왕성 곁을 지났습니다. 같은 천문대의 베스토 슬라이퍼는 1912년 안드로메다 은하가 초속 300km쯤으로 우리를 향해 다가온다는 것을 쟀고, 이후 대부분의 은하가 멀어지고 있음을 보였습니다."),
  palomar: t("헤일 망원경의 거울은 갈아 다듬는 동안 무게가 약 20톤에서 14.5톤으로 줄었습니다. 팔로마에서 처음 사진을 찍은 사람은 1949년 1월 26일 에드윈 허블이었습니다. 1963년에는 마르턴 슈미트가 이 망원경으로 3C 273이라는 밝은 천체의 빛을 분석해, 지구에서 20억 광년 넘게 떨어진 퀘이사임을 알았습니다. 퀘이사가 먼 은하의 중심에서 나오는 빛임을 알리는 첫 단서였습니다. 팔로마산의 48인치 슈미트 망원경은 1949년부터 1958년까지 북쪽 하늘 전체의 사진 지도를 만들었습니다."),
  vla: t("1991년 수성 북극의 밝은 레이더 점을 잡은 것이 이곳입니다. 캘리포니아의 골드스톤 안테나가 전파를 쏘고, VLA가 되돌아온 전파를 받았습니다. 2012년 장비를 새로 바꾸면서 칼 잰스키 VLA로 이름을 바꿨는데, 잰스키는 1930년대 초에 우주에서 오는 전파를 처음 찾은 사람입니다. 접시를 가장 모으는 D 배치에서는 지름 1km, 가장 넓히는 A 배치에서는 36km의 접시와 맞먹는 선명함을 냅니다. Y자 레일 한 줄의 길이는 약 21km이고, 접시는 28대 가운데 하나가 예비입니다."),
  luna3: t("루나 3호보다 앞서 1959년 1월 루나 1호가 달 곁 약 6,000km를 스쳐 태양 둘레를 도는 첫 인공 천체가 되었고, 9월 14일 루나 2호는 달에 닿은 첫 우주선이 되었습니다. 루나 3호가 찍은 사진은 흐릿했지만 달 뒷면에 바다가 적다는 사실을 알기에는 충분했습니다. 뒷면의 지각이 앞면보다 두꺼워 용암이 올라오기 어려웠던 것이 그 까닭으로 봅니다. 루나 3호의 카메라는 초점 거리가 서로 다른 렌즈 두 개를 달고 있어, 달 전체와 일부를 따로 담았습니다."),
  cheomseongdae: t("첨성대는 2000년에 지정된 경주역사유적지구 안에 있습니다. 신라는 기원전 57년부터 935년까지 약 천 년 동안 경주를 도읍으로 삼았습니다. 선덕여왕은 한국 역사에서 기록에 남은 첫 여왕입니다. 같은 시기인 645년에는 황룡사에 9층 목탑이 세워졌는데 높이가 80m쯤이었다고 추정합니다. 이 탑은 1238년 몽골 침입 때 불타 사라졌고, 첨성대는 그 시절을 지켜본 몇 안 되는 건물로 남았습니다. 첨성대는 별을 보는 대라는 뜻입니다. 아래쪽 지름은 5m가 조금 넘고 꼭대기는 3m가 못 됩니다."),
  stonehenge: t("서 있는 사르센 돌 서른 개가 원을 이루고, 그 위에 가로돌 서른 개를 얹었습니다. 가로돌은 밑면의 홈을 서 있는 돌 꼭대기의 돌기에 끼워 맞췄고, 가로돌끼리는 끝을 턱지게 깎아 서로 이었습니다. 목수가 나무를 짜 맞추는 방식을 돌에 쓴 것입니다. 돌의 원은 바깥 지름이 약 30m이고, 안쪽에는 높이 6 → 7m의 거대한 문 모양 돌 틀 다섯 벌이 말굽 모양으로 서 있습니다. 1915년 경매에 나온 이 땅을 세실 추브가 6,600파운드에 샀다가 1918년 나라에 기증했습니다."),
  arecibo: t("접시 위 150m 높이에는 무게 900톤쯤의 수신 장치가 케이블 18가닥으로 탑 세 개에 매달려 있었습니다. 접시는 깊이가 51m였고, 바닥에는 알루미늄 판 4만 장 가까이 깔려 있었습니다. 2016년 이곳의 자료에서 FRB 121102라는, 짧고 강한 전파 폭발이 되풀이해서 오는 천체가 확인되었습니다. 되풀이되는 빠른 전파 폭발이 확인된 첫 사례였고, 지금도 그 정체를 놓고 연구가 이어지고 있습니다. 처음에는 미국 국방부가 지구 대기 위쪽을 연구하려고 짓기 시작한 시설이었습니다."),
};
